 47→            md.push_str("\n## Summary\n\n");
 48→            md.push_str(summary);
 49→            md.push('\n');
 50→        }
 51→
 52→        if !self.dead_ends.is_empty() {
 53→            md.push_str("\n## Dead Ends\n\n");
 54→            for de in &self.dead_ends {
 55→                md.push_str(&format!("- **{}**: {}\n", de.approach, de.reason));
 56→            }
 57→        }
 58→
 59→        if !self.decisions.is_empty() {
