 69→    /// Parse from Markdown
 70→    pub fn from_markdown(md: &str) -> Result<Self, CoreError> {
 71→        let mut original_request = String::new();
 72→        let mut interpreted_goal = None;
 73→        let mut summary = None;
 74→        let mut dead_ends = Vec::new();
 75→        let mut decisions = Vec::new();
 76→
 77→        let mut current_section = "intent";
 78→        let mut current_content = String::new();
 79→
 80→        for line in md.lines() {
 81→            if line.starts_with("# Intent") {
 82→                current_section = "intent";
 83→                current_content.clear();
 84→                continue;
 85→            } else if line.starts_with("## Original Request") {
 86→                // Backward compat: treat as intent section (some SDKs used this heading)
 87→                Self::save_section(
 88→                    current_section,
 89→                    &current_content,
 90→                    &mut original_request,
 91→                    &mut interpreted_goal,
 92→                    &mut summary,
 93→                );
 94→                current_section = "intent";
 95→                current_content.clear();
 96→                continue;
 97→            } else if line.starts_with("## Interpreted Goal") {
 98→                // Save previous section
 99→                Self::save_section(
100→                    current_section,
101→                    &current_content,
102→                    &mut original_request,
103→                    &mut interpreted_goal,
104→                    &mut summary,
105→                );
106→                current_section = "goal";
107→                current_content.clear();
108→                continue;
109→            } else if line.starts_with("## Summary") {
110→                Self::save_section(
111→                    current_section,
112→                    &current_content,
113→                    &mut original_request,
114→                    &mut interpreted_goal,
115→                    &mut summary,
116→                );
117→                current_section = "summary";
118→                current_content.clear();
119→                continue;
120→            } else if line.starts_with("## Dead Ends") {
121→                Self::save_section(
122→                    current_section,
