152→                        }
153→                    }
154→                }
155→                "decisions" => {
156→                    if let Some(entry) = line.strip_prefix("- **") {
157→                        if let Some((desc, rationale)) = entry.split_once("**: ") {
158→                            decisions.push(Decision {
159→                                description: desc.to_string(),
160→                                rationale: rationale.to_string(),
161→                            });
162→                        }
163→                    }
164→                }
165→                _ => {
166→                    if !current_content.is_empty() || !line.is_empty() {
167→                        if !current_content.is_empty() {
168→                            current_content.push('\n');
169→                        }
170→                        current_content.push_str(line);
171→                    }
172→                }
173→            }
174→        }
175→
176→        // Save last section
177→        Self::save_section(
178→            current_section,
179→            &current_content,
180→            &mut original_request,
181→            &mut interpreted_goal,
182→            &mut summary,
183→        );
184→
185→        Ok(Intent {
186→            original_request,
187→            interpreted_goal,
