192→    }
193→
194→    fn save_section(
195→        section: &str,
196→        content: &str,
197→        original_request: &mut String,
198→        interpreted_goal: &mut Option<String>,
199→        summary: &mut Option<String>,
200→    ) {
201→        let trimmed = content.trim().to_string();
202→        if trimmed.is_empty() {
