29→pub fn run(args: &LogArgs, format: OutputFormat) -> Result<()> {
30→    let storage = GitStorage::discover().context("Not inside a Git repository")?;
31→
32→    if !storage.is_initialized() {
33→        anyhow::bail!("Engram is not initialized. Run `engram init` first.");
34→    }
35→
36→    let opts = ListOptions {
37→        limit: Some(args.limit),
38→        agent_filter: args.agent.clone(),
39→    };
