243→        assert_eq!(review.total_tokens, 5000);
244→        let cost = review.total_cost.unwrap();
245→        assert!((cost - 0.10).abs() < 1e-10);
246→        assert!(review.files_changed.contains(&"src/auth.rs".to_string()));
247→    }
