    fn test_estimate_cost_unknown_model() {
        let usage = TokenUsage {
            input_tokens: 1000,
            output_tokens: 500,
            total_tokens: 1500,
            ..Default::default()
        };
        assert!(estimate_cost(Some("llama-3.1-70b"), &usage).is_none());
    }

