 53→/// Handle the `post-commit` hook.
 54→///
 55→/// If an active engram session exists, records the new commit SHA.
 56→pub fn handle_post_commit(git_dir: &Path) -> Result<(), CoreError> {
 57→    let mut session = match ActiveSession::load(git_dir) {
 58→        Some(s) => s,
 59→        None => return Ok(()),
 60→    };
 61→
 62→    // Read HEAD to get the new commit SHA
 63→    let repo = git2::Repository::open(git_dir.parent().unwrap_or(git_dir))?;
 64→    let head = repo.head()?;
 65→    let sha = head.target().map(|oid| oid.to_string()).unwrap_or_default();
 66→
 67→    if !sha.is_empty() {
 68→        session.add_commit(&sha, git_dir)?;
 69→    }
 70→
 71→    Ok(())
 72→}
