241→/// After post-commit, if the session was auto-created, update the engram
242→/// with the commit SHA and clean up the session file.
243→fn maybe_auto_capture_cleanup(storage: &GitStorage, git_dir: &std::path::Path) {
244→    let session = match ActiveSession::load(git_dir) {
245→        Some(s) if s.auto_capture => s,
246→        _ => return,
247→    };
248→
249→    // The core post-commit handler already recorded the commit SHA in the session.
250→    // Now read back the session to get the commit, update the engram, and clean up.
251→    let updated = ActiveSession::load(git_dir).unwrap_or(session);
252→
253→    if !updated.commits.is_empty() {
254→        // Re-read the engram, update its git_commits, and re-store it
255→        if let Ok(mut data) = storage.read(updated.engram_id.as_str()) {
256→            for sha in &updated.commits {
257→                if !data.manifest.git_commits.contains(sha) {
258→                    data.manifest.git_commits.push(sha.clone());
259→                }
260→                if !data.lineage.git_commits.contains(sha) {
261→                    data.lineage.git_commits.push(sha.clone());
262→                }
263→            }
264→            // Re-store the updated engram (overwrites the ref)
265→            let _ = storage.create(&data);
266→        }
267→    }
268→
269→    ActiveSession::cleanup(git_dir);
270→    tracing::debug!(
271→        "Auto-capture: finalized engram {} with {} commit(s)",
272→        &updated.engram_id.as_str()[..8],
273→        updated.commits.len()
274→    );
275→}
