134→/// If auto_capture is enabled and no active session exists, discover and import
135→/// the most recent Claude Code session, then create a temporary ActiveSession
136→/// so the prepare-commit-msg handler can inject trailers.
137→fn maybe_auto_capture(storage: &GitStorage, git_dir: &std::path::Path) {
138→    // Don't interfere with an existing session (e.g. from `engram record`)
139→    if ActiveSession::load(git_dir).is_some() {

140→        return;
141→    }
142→
143→    let config = match load_config(storage) {
144→        Some(c) => c,
145→        None => return,
146→    };
147→
148→    if !config.auto_capture {
149→        return;
150→    }
151→
152→    let workdir = match storage.workdir() {
153→        Some(w) => w.to_path_buf(),
154→        None => return,
155→    };
156→
157→    // Discover Claude Code session files for this project
158→    let session_files = match ClaudeCodeImporter::discover_sessions(&workdir) {
159→        Ok(files) => files,
160→        Err(e) => {
161→            tracing::debug!("Auto-capture: failed to discover sessions: {e}");
162→            return;
163→        }
164→    };
165→
166→    if session_files.is_empty() {
167→        tracing::debug!("Auto-capture: no Claude Code sessions found");
168→        return;
169→    }
170→
171→    // Pick the most recently modified session file
172→    let newest = session_files
173→        .into_iter()
174→        .filter_map(|p| {
175→            let mtime = std::fs::metadata(&p).ok()?.modified().ok()?;
176→            Some((p, mtime))
177→        })
178→        .max_by_key(|(_, mtime)| *mtime)
179→        .map(|(p, _)| p);
180→
181→    let session_path = match newest {
182→        Some(p) => p,
183→        None => return,
184→    };
185→
186→    // Import the session
187→    let data = match ClaudeCodeImporter::import_session(&session_path) {
188→        Ok(d) => d,
189→        Err(e) => {
190→            tracing::debug!("Auto-capture: failed to import session: {e}");
191→            return;
192→        }
193→    };
194→
195→    // Check for duplicates — if already imported, reuse the existing engram ID
196→    let engram_id = if let Some(existing_id) = data
197→        .manifest
198→        .source_hash
199→        .as_deref()
200→        .and_then(|h| storage.find_by_source_hash(h))
201→    {
202→        // Already imported this exact snapshot — reuse the ID
203→        existing_id
204→    } else {
205→        // New content — store the engram
206→        let id = data.manifest.id.clone();
207→        match storage.create(&data) {
208→            Ok(_) => {
209→                // Best-effort index update
210→                if let Ok(engine) = SearchEngine::open(storage) {
211→                    let _ = engine.index_engram(&data);
212→                }
213→                tracing::debug!("Auto-capture: imported engram {}", &id.as_str()[..8]);
214→                id
215→            }
216→            Err(e) => {
217→                tracing::debug!("Auto-capture: failed to store engram: {e}");
218→                return;
219→            }
220→        }
221→    };
222→
223→    // Create a temporary ActiveSession so the core handler can inject trailers
224→    let agent = data.manifest.agent.clone();
225→    let mut session = ActiveSession::new(
226→        engram_id,
227→        AgentInfo {
228→            name: agent.name,
229→            model: agent.model,
230→            version: agent.version,
231→        },
232→    );
233→    session.token_usage = data.manifest.token_usage.clone();
234→    session.auto_capture = true;
235→
236→    if let Err(e) = session.save(git_dir) {
237→        tracing::debug!("Auto-capture: failed to save session: {e}");
238→    }
239→}

  1→use git2::Repository;
