  3→use crate::error::ProtocolError;
  4→
  5→/// Refspec for fetching engram refs from remotes.
  6→pub const ENGRAM_FETCH_REFSPEC: &str = "+refs/engrams/*:refs/engrams/*";
  7→
  8→/// Refspec for pushing engram refs to remotes.
  9→pub const ENGRAM_PUSH_REFSPEC: &str = "refs/engrams/*:refs/engrams/*";
 10→
 11→/// Ensure the engram refspecs are configured for a remote.
 12→pub fn ensure_refspecs(repo: &Repository, remote_name: &str) -> Result<bool, ProtocolError> {
 13→    let remote = repo
 14→        .find_remote(remote_name)
 15→        .map_err(|_| ProtocolError::RemoteNotFound(remote_name.into()))?;
 16→
 17→    let mut needs_fetch = true;
 18→    let mut needs_push = true;
 19→
 20→    // Check existing fetch refspecs
 21→    if let Ok(refspecs) = remote.fetch_refspecs() {
 22→        for i in 0..refspecs.len() {
 23→            if let Some(spec) = refspecs.get(i) {
 24→                if spec == ENGRAM_FETCH_REFSPEC {
 25→                    needs_fetch = false;
 26→                }
 27→            }
 28→        }
 29→    }
 30→
 31→    // Check existing push refspecs
 32→    if let Ok(refspecs) = remote.push_refspecs() {
 33→        for i in 0..refspecs.len() {
 34→            if let Some(spec) = refspecs.get(i) {
 35→                if spec == ENGRAM_PUSH_REFSPEC {
 36→                    needs_push = false;
 37→                }
 38→            }
 39→        }
 40→    }
 41→
 42→    drop(remote);
 43→
 44→    let mut changed = false;
 45→
 46→    if needs_fetch {
 47→        repo.remote_add_fetch(remote_name, ENGRAM_FETCH_REFSPEC)?;
 48→        changed = true;
 49→    }
 50→
 51→    if needs_push {
 52→        repo.remote_add_push(remote_name, ENGRAM_PUSH_REFSPEC)?;
 53→        changed = true;
 54→    }
 55→
 56→    Ok(changed)
 57→}
 58→
 59→/// Ensure refspecs for all remotes in the repository.
 60→pub fn ensure_all_refspecs(repo: &Repository) -> Result<Vec<String>, ProtocolError> {
 61→    let remotes = repo.remotes()?;
 62→    let mut configured = Vec::new();
 63→
 64→    for i in 0..remotes.len() {
 65→        if let Some(name) = remotes.get(i) {
 66→            if ensure_refspecs(repo, name)? {
 67→                configured.push(name.to_string());
 68→            }
 69→        }
 70→    }
 71→
 72→    Ok(configured)
 73→}
