 5→
 6→#[derive(Args)]
 7→pub struct InitArgs {
 8→    /// Force re-initialization
 9→    #[arg(long)]
10→    pub force: bool,
11→
12→    /// Remote name to configure refspecs on (default: all remotes)
13→    #[arg(long)]
14→    pub remote: Option<String>,
15→
16→    /// Configure Claude Code SessionEnd hook for auto-capture
17→    #[arg(long)]
18→    pub claude_code: bool,
19→}
20→
21→pub fn run(args: &InitArgs) -> Result<()> {
22→    let storage =
23→        GitStorage::discover().context("Not inside a Git repository. Run `git init` first.")?;
24→
25→    if storage.is_initialized() && !args.force {
26→        // Even if already initialized, allow --claude-code to be added
27→        if args.claude_code {
28→            let workdir = storage
29→                .workdir()
30→                .ok_or_else(|| anyhow::anyhow!("Cannot determine working directory"))?;
31→            hooks::install_claude_code_hook(workdir)
32→                .context("Failed to configure Claude Code hook")?;
33→            println!("Claude Code SessionEnd hook configured.");
34→            println!("  Sessions will be auto-imported when Claude Code exits.");
35→            return Ok(());
36→        }
37→        println!("Engram is already initialized in this repository.");
38→        println!("Use --force to re-initialize.");
39→        return Ok(());
40→    }
41→
42→    storage
43→        .init_with_remote(args.remote.as_deref())
44→        .context("Failed to initialize engram")?;
45→
46→    // Install git hooks for commit trailer injection
47→    let git_dir = storage.repo().path().to_path_buf();
48→    hooks::install_hooks(&git_dir).context("Failed to install git hooks")?;
49→
50→    if args.claude_code {
51→        let workdir = storage
52→            .workdir()
53→            .ok_or_else(|| anyhow::anyhow!("Cannot determine working directory"))?;
54→        hooks::install_claude_code_hook(workdir).context("Failed to configure Claude Code hook")?;
55→        println!("Claude Code SessionEnd hook configured.");
56→        println!("  Sessions will be auto-imported when Claude Code exits.");
57→        println!();
58→    }
59→
60→    println!("Engram initialized. Reasoning capture is ready.");
61→    println!();
62→    println!("Next steps:");
63→    println!("  engram record -- <agent-command>   Record an agent session");
64→    println!("  engram import --auto-detect        Import existing sessions");
65→    println!("  engram log                         List captured engrams");
66→    Ok(())
67→}
