 53→fn print_narrative(file: &str, entries: &[engram_core::model::EngramData]) {
 54→    println!("Why does `{}` exist?", file);
 55→    println!("{}", "=".repeat(20 + file.len()));
 56→    println!();
 57→
 58→    let mut total_tokens: u64 = 0;
 59→    let mut total_cost: f64 = 0.0;
 60→
 61→    for (i, data) in entries.iter().enumerate() {
 62→        let m = &data.manifest;
 63→        total_tokens += m.token_usage.total_tokens;
 64→        total_cost += m
 65→            .token_usage
 66→            .effective_cost(m.agent.model.as_deref())
 67→            .unwrap_or(0.0);
 68→
 69→        let date = m.created_at.format("%Y-%m-%d %H:%M");
 70→        let agent = &m.agent.name;
 71→        let model = m.agent.model.as_deref().unwrap_or("unknown");
 72→
 73→        // Find the file change for this specific file
 74→        let file_change = data
 75→            .operations
 76→            .file_changes
 77→            .iter()
 78→            .find(|fc| fc.path == file);
 79→
 80→        let change_desc = file_change
 81→            .map(|fc| {
 82→                let action = match &fc.change_type {
 83→                    FileChangeType::Created => "Created",
 84→                    FileChangeType::Modified => "Modified",
 85→                    FileChangeType::Deleted => "Deleted",
 86→                    FileChangeType::Renamed { from } => {
 87→                        return format!("Renamed from {from}");
 88→                    }
 89→                };
 90→                let lines = match (fc.lines_added, fc.lines_removed) {
 91→                    (Some(a), Some(r)) => format!(" (+{a}/-{r} lines)"),
 92→                    (Some(a), None) => format!(" (+{a} lines)"),
 93→                    (None, Some(r)) => format!(" (-{r} lines)"),
 94→                    (None, None) => String::new(),
 95→                };
 96→                format!("{action}{lines}")
 97→            })
 98→            .unwrap_or_else(|| "Touched".to_string());
 99→
100→        // Chapter header
101→        println!(
102→            "{}. [{}] {} ({}) — {}",
103→            i + 1,
104→            date,
105→            agent,
106→            model,
107→            change_desc
108→        );
109→
110→        // Request
111→        println!("   Request: \"{}\"", data.intent.original_request);
112→
113→        // Goal (if different from request)
114→        if let Some(goal) = &data.intent.interpreted_goal {
115→            if goal != &data.intent.original_request {
116→                println!("   Goal: {goal}");
117→            }
118→        }
119→
120→        // What happened
121→        if let Some(summary) = data.intent.summary.as_deref().or(m.summary.as_deref()) {
122→            println!("   Result: {summary}");
123→        }
124→
125→        // Dead ends
126→        if !data.intent.dead_ends.is_empty() {
127→            println!("   Dead ends:");
128→            for de in &data.intent.dead_ends {
129→                println!("     - {}: {}", de.approach, de.reason);
130→            }
131→        }
132→
133→        // Decisions
134→        if !data.intent.decisions.is_empty() {
135→            println!("   Decisions:");
136→            for d in &data.intent.decisions {
137→                println!("     - {}: {}", d.description, d.rationale);
138→            }
139→        }
140→
141→        println!();
142→    }
143→
144→    // Footer
145→    println!("{}", "-".repeat(50));
146→    println!(
147→        "{} sessions touched this file | {} tokens | ${:.2} total cost",
148→        entries.len(),
149→        total_tokens,
150→        total_cost
151→    );
152→}
