184→    /// Update the engram-head pointer file. Only updates if this engram is newer.
185→    /// Best-effort — failures are silently ignored.
186→    fn update_head_pointer(&self, id: &EngramId, created_at: &chrono::DateTime<chrono::Utc>) {
187→        // repo.path() returns the .git dir (or the repo dir for bare repos)
188→        let head_path = self.repo.path().join(ENGRAM_HEAD_FILE);
189→
190→        // Read existing pointer to check timestamp
191→        if let Ok(existing) = std::fs::read_to_string(&head_path) {
192→            // Format: "<id> <rfc3339-timestamp>"
193→            if let Some(ts_str) = existing.split_whitespace().nth(1) {
194→                if let Ok(existing_ts) = ts_str.parse::<chrono::DateTime<chrono::Utc>>() {
195→                    if existing_ts >= *created_at {
196→                        return; // Existing head is newer or same
197→                    }
198→                }
199→            }
200→        }
201→
202→        let content = format!("{} {}", id.as_str(), created_at.to_rfc3339());
203→        let _ = std::fs::write(&head_path, content);
204→    }
205→
206→    /// Read the engram-head pointer file. Returns the ID if valid.
207→    fn read_head_pointer(&self) -> Option<String> {
208→        let head_path = self.repo.path().join(ENGRAM_HEAD_FILE);
209→        let content = std::fs::read_to_string(&head_path).ok()?;
210→        content.split_whitespace().next().map(String::from)
211→    }
212→
213→    /// Configure fetch/push refspecs for engram refs on remotes.
214→    /// If `filter` is Some, only configure that specific remote.
215→    fn configure_remotes_filtered(&self, filter: Option<&str>) -> Result<(), CoreError> {
216→        let remotes = self.repo.remotes().map_err(CoreError::Git)?;
217→        let mut config = self.repo.config().map_err(CoreError::Git)?;
218→
219→        for remote_name in remotes.iter().flatten() {
220→            if let Some(target) = filter {
221→                if remote_name != target {
222→                    continue;
223→                }
224→            }
225→            let fetch_key = format!("remote.{remote_name}.fetch");
226→            let push_key = format!("remote.{remote_name}.push");
227→            let fetch_refspec = "+refs/engrams/*:refs/engrams/*";
228→            let push_refspec = "refs/engrams/*:refs/engrams/*";
229→
230→            // Check if already configured by iterating existing values
231→            let fetch_exists = config
232→                .entries(Some(&fetch_key))
233→                .ok()
234→                .map(|mut entries| {
235→                    let mut found = false;
236→                    while let Some(Ok(entry)) = entries.next() {
237→                        if entry.value() == Some(fetch_refspec) {
238→                            found = true;
239→                            break;
240→                        }
241→                    }
242→                    found
243→                })
244→                .unwrap_or(false);
245→
246→            if !fetch_exists {
247→                config
248→                    .set_multivar(&fetch_key, "^$", fetch_refspec)
249→                    .or_else(|_| {
250→                        // If set_multivar fails (no existing entry), try adding
251→                        self.repo
252→                            .remote_add_fetch(remote_name, fetch_refspec)
253→                            .map(|_| ())
254→                    })
255→                    .map_err(CoreError::Git)?;
256→            }
257→
258→            let push_exists = config
259→                .entries(Some(&push_key))
260→                .ok()
261→                .map(|mut entries| {
262→                    let mut found = false;
263→                    while let Some(Ok(entry)) = entries.next() {
264→                        if entry.value() == Some(push_refspec) {
265→                            found = true;
266→                            break;
267→                        }
268→                    }
269→                    found
270→                })
271→                .unwrap_or(false);
272→
273→            if !push_exists {
274→                config
275→                    .set_multivar(&push_key, "^$", push_refspec)
276→                    .or_else(|_| {
277→                        self.repo
278→                            .remote_add_push(remote_name, push_refspec)
279→                            .map(|_| ())
280→                    })
281→                    .map_err(CoreError::Git)?;
282→            }
283→        }
284→
285→        Ok(())
286→    }
287→}
