 10→pub struct StatsArgs {
 11→    /// Show cost and token breakdown by file
 12→    #[arg(long)]
 13→    pub by_file: bool,
 14→
 15→    /// Show cost and token breakdown by branch
 16→    #[arg(long)]
 17→    pub by_branch: bool,
 18→
 19→    /// Show daily cost trend for the last 30 days
 20→    #[arg(long)]
 21→    pub trend: bool,
 22→
 23→    /// Maximum number of entries in breakdowns
 24→    #[arg(long, default_value = "10")]
 25→    pub top: usize,
 26→}
 27→
 28→pub fn run(args: &StatsArgs, format: OutputFormat) -> Result<()> {
 29→    let storage = GitStorage::discover().context("Not inside a Git repository")?;
 30→
 31→    if !storage.is_initialized() {
 32→        anyhow::bail!("Engram is not initialized. Run `engram init` first.");
 33→    }
 34→
 35→    let manifests = storage
 36→        .list(&ListOptions::default())
 37→        .context("Failed to list engrams")?;
 38→
 39→    if manifests.is_empty() {
 40→        println!("No engrams found.");
 41→        return Ok(());
 42→    }
 43→
 44→    // If a specific breakdown was requested, run that and return
 45→    if args.by_file {
 46→        return run_by_file(&storage, &manifests, args.top, format);
 47→    }
 48→    if args.by_branch {
 49→        return run_by_branch(&storage, &manifests, args.top, format);
 50→    }
 51→    if args.trend {
 52→        return run_trend(&manifests, format);
 53→    }
 54→
 55→    // Default: show aggregate stats (original behavior)
 56→    run_aggregate(&manifests, format)
 57→}
