 59→fn run_aggregate(manifests: &[engram_core::model::Manifest], format: OutputFormat) -> Result<()> {
 60→    let total = manifests.len();
 61→    let mut total_tokens: u64 = 0;
 62→    let mut total_cost: f64 = 0.0;
 63→    let mut by_agent: BTreeMap<String, (usize, u64, f64)> = BTreeMap::new();
 64→    let mut by_mode: BTreeMap<String, usize> = BTreeMap::new();
 65→
 66→    let earliest = manifests.last().map(|m| m.created_at);
 67→    let latest = manifests.first().map(|m| m.created_at);
 68→
 69→    for m in manifests {
 70→        let cost = m
 71→            .token_usage
 72→            .effective_cost(m.agent.model.as_deref())
 73→            .unwrap_or(0.0);
 74→        total_tokens += m.token_usage.total_tokens;
 75→        total_cost += cost;
 76→
 77→        let entry = by_agent.entry(m.agent.name.clone()).or_default();
 78→        entry.0 += 1;
 79→        entry.1 += m.token_usage.total_tokens;
 80→        entry.2 += cost;
 81→
 82→        *by_mode.entry(format!("{:?}", m.capture_mode)).or_default() += 1;
 83→    }
 84→
 85→    match format {
 86→        OutputFormat::Json => {
 87→            let stats = serde_json::json!({
 88→                "total_engrams": total,
 89→                "total_tokens": total_tokens,
 90→                "total_cost_usd": total_cost,
 91→                "earliest": earliest,
 92→                "latest": latest,
 93→                "by_agent": by_agent.iter().map(|(name, (count, tokens, cost))| {
 94→                    serde_json::json!({
 95→                        "agent": name,
 96→                        "count": count,
 97→                        "tokens": tokens,
 98→                        "cost_usd": cost,
 99→                    })
100→                }).collect::<Vec<_>>(),
101→                "by_capture_mode": by_mode,
102→            });
103→            println!("{}", serde_json::to_string_pretty(&stats).unwrap());
104→        }
105→        OutputFormat::Text | OutputFormat::Markdown => {
106→            println!("Engram Statistics");
107→            println!("=================");
108→            println!("Total engrams:  {total}");
109→            println!("Total tokens:   {total_tokens}");
110→            println!("Total cost:     ${total_cost:.2}");
111→            if let (Some(e), Some(l)) = (earliest, latest) {
112→                println!(
113→                    "Date range:     {} to {}",
114→                    e.format("%Y-%m-%d"),
115→                    l.format("%Y-%m-%d")
116→                );
117→            }
118→            println!();
119→
120→            println!("By Agent:");
121→            for (name, (count, tokens, cost)) in &by_agent {
122→                println!("  {name}: {count} engrams, {tokens} tokens, ${cost:.2}");
123→            }
124→            println!();
125→
126→            println!("By Capture Mode:");
127→            for (mode, count) in &by_mode {
128→                println!("  {mode}: {count}");
129→            }
130→        }
131→    }
132→
133→    Ok(())
134→}
