136→fn run_by_file(
137→    storage: &GitStorage,
138→    manifests: &[engram_core::model::Manifest],
139→    top: usize,
140→    format: OutputFormat,
141→) -> Result<()> {
142→    // Accumulate (sessions, tokens, cost) per file
143→    let mut by_file: BTreeMap<String, (usize, u64, f64)> = BTreeMap::new();
144→
145→    for m in manifests {
146→        if let Ok(data) = storage.read(m.id.as_str()) {
147→            let session_tokens = m.token_usage.total_tokens;
148→            let session_cost = m
149→                .token_usage
150→                .effective_cost(m.agent.model.as_deref())
151→                .unwrap_or(0.0);
152→            let file_count = data.operations.file_changes.len();
153→
154→            if file_count == 0 {
155→                continue;
156→            }
157→
158→            // Distribute session cost evenly across files touched
159→            let per_file_tokens = session_tokens / file_count as u64;
160→            let per_file_cost = session_cost / file_count as f64;
161→
162→            for fc in &data.operations.file_changes {
163→                let entry = by_file.entry(fc.path.clone()).or_default();
164→                entry.0 += 1;
165→                entry.1 += per_file_tokens;
166→                entry.2 += per_file_cost;
167→            }
168→        }
169→    }
170→
171→    // Sort by cost descending
172→    let mut sorted: Vec<_> = by_file.into_iter().collect();
173→    sorted.sort_by(|a, b| {
174→        b.1 .2
175→            .partial_cmp(&a.1 .2)
176→            .unwrap_or(std::cmp::Ordering::Equal)
177→    });
178→    sorted.truncate(top);
179→
180→    match format {
181→        OutputFormat::Json => {
182→            let entries: Vec<_> = sorted
183→                .iter()
184→                .map(|(path, (sessions, tokens, cost))| {
185→                    serde_json::json!({
186→                        "file": path,
187→                        "sessions": sessions,
188→                        "tokens": tokens,
189→                        "cost_usd": cost,
190→                    })
191→                })
192→                .collect();
193→            println!("{}", serde_json::to_string_pretty(&entries).unwrap());
194→        }
195→        OutputFormat::Text | OutputFormat::Markdown => {
196→            println!("Cost by File (top {top})");
197→            println!("{}", "=".repeat(60));
198→            println!(
199→                "{:<40} {:>8} {:>10} {:>8}",
200→                "File", "Sessions", "Tokens", "Cost"
201→            );
202→            println!("{}", "-".repeat(60));
203→            for (path, (sessions, tokens, cost)) in &sorted {
204→                let display_path = if path.len() > 38 {
205→                    format!("...{}", &path[path.len() - 35..])
206→                } else {
207→                    path.clone()
208→                };
209→                println!(
210→                    "{:<40} {:>8} {:>10} ${:>7.2}",
211→                    display_path, sessions, tokens, cost
212→                );
213→            }
214→        }
215→    }
216→
217→    Ok(())
218→}
