297→fn run_trend(manifests: &[engram_core::model::Manifest], format: OutputFormat) -> Result<()> {
298→    use chrono::{Duration, Utc};
299→
300→    let cutoff = Utc::now() - Duration::days(30);
301→    let today = Utc::now().date_naive();
302→
303→    // Bucket by date
304→    let mut by_date: BTreeMap<chrono::NaiveDate, (usize, u64, f64)> = BTreeMap::new();
305→
306→    for m in manifests {
307→        if m.created_at < cutoff {
308→            continue;
309→        }
310→        let cost = m
311→            .token_usage
312→            .effective_cost(m.agent.model.as_deref())
313→            .unwrap_or(0.0);
314→        let date = m.created_at.date_naive();
315→        let entry = by_date.entry(date).or_default();
316→        entry.0 += 1;
317→        entry.1 += m.token_usage.total_tokens;
318→        entry.2 += cost;
319→    }
320→
321→    match format {
322→        OutputFormat::Json => {
323→            let entries: Vec<_> = by_date
324→                .iter()
325→                .map(|(date, (sessions, tokens, cost))| {
326→                    serde_json::json!({
327→                        "date": date.to_string(),
328→                        "sessions": sessions,
329→                        "tokens": tokens,
330→                        "cost_usd": cost,
331→                    })
332→                })
333→                .collect();
334→            println!("{}", serde_json::to_string_pretty(&entries).unwrap());
335→        }
336→        OutputFormat::Text | OutputFormat::Markdown => {
337→            println!("Cost Trend (last 30 days)");
338→            println!("{}", "=".repeat(50));
339→            println!(
340→                "{:<12} {:>8} {:>12} {:>8}",
341→                "Date", "Sessions", "Tokens", "Cost"
342→            );
343→            println!("{}", "-".repeat(50));
344→
345→            // Fill in days with no activity
346→            let start =
347→                (today - Duration::days(29)).max(by_date.keys().next().copied().unwrap_or(today));
348→            let mut date = start;
349→            while date <= today {
350→                let (sessions, tokens, cost) = by_date.get(&date).copied().unwrap_or((0, 0, 0.0));
351→                if sessions > 0 {
352→                    println!("{:<12} {:>8} {:>12} ${:>7.2}", date, sessions, tokens, cost);
353→                }
354→                date += Duration::days(1);
355→            }
356→
357→            // Summary
358→            let total_cost: f64 = by_date.values().map(|v| v.2).sum();
359→            let total_sessions: usize = by_date.values().map(|v| v.0).sum();
360→            let active_days = by_date.len();
361→            println!("{}", "-".repeat(50));
362→            println!(
363→                "Total: {total_sessions} sessions over {active_days} active days, ${total_cost:.2}"
364→            );
365→        }
366→    }
367→
368→    Ok(())
369→}
