  1→use std::collections::{HashMap, HashSet};
  2→
  3→use anyhow::{Context, Result};
  4→use clap::Args;
  5→use engram_core::notes::{format_note, ENGRAM_NOTES_REF};
  6→use engram_core::storage::{GitStorage, ListOptions};
  7→
  8→#[derive(Args)]
  9→pub struct AnnotateArgs {
 10→    /// Git range to annotate (e.g., "main..HEAD"). If omitted, annotates all linked commits.
 11→    pub range: Option<String>,
 12→
 13→    /// Preview what would be annotated without writing notes
 14→    #[arg(long)]
 15→    pub dry_run: bool,
 16→
 17→    /// Overwrite existing notes
 18→    #[arg(long)]
 19→    pub force: bool,
 20→}
 21→
 22→pub fn run(args: &AnnotateArgs) -> Result<()> {
 23→    let storage = GitStorage::discover().context("Not inside a Git repository")?;
 24→
 25→    if !storage.is_initialized() {
 26→        anyhow::bail!("Engram is not initialized. Run `engram init` first.");
 27→    }
 28→
 29→    let repo = storage.repo();
 30→
 31→    // Collect allowed commit SHAs if a range is specified
 32→    let range_filter: Option<HashSet<String>> = if let Some(range) = &args.range {
 33→        let mut shas = HashSet::new();
 34→        let parts: Vec<&str> = range.split("..").collect();
 35→        if parts.len() != 2 {
 36→            anyhow::bail!("Invalid range format. Expected 'base..head' (e.g., 'main..HEAD').");
 37→        }
 38→        let base_obj = repo
 39→            .revparse_single(parts[0])
 40→            .context(format!("Cannot resolve '{}'", parts[0]))?;
 41→        let head_obj = repo
 42→            .revparse_single(parts[1])
 43→            .context(format!("Cannot resolve '{}'", parts[1]))?;
 44→
 45→        let mut revwalk = repo.revwalk().context("Cannot create revwalk")?;
 46→        revwalk
 47→            .push(head_obj.id())
 48→            .context("Cannot push head to revwalk")?;
 49→        revwalk
 50→            .hide(base_obj.id())
 51→            .context("Cannot hide base in revwalk")?;
 52→
 53→        for oid in revwalk {
 54→            let oid = oid.context("Revwalk error")?;
 55→            shas.insert(oid.to_string());
 56→        }
 57→        Some(shas)
 58→    } else {
 59→        None
 60→    };
 61→
 62→    // Build a map of commit SHA -> engram data
 63→    let manifests = storage
 64→        .list(&ListOptions::default())
 65→        .context("Failed to list engrams")?;
 66→
 67→    // Map commit SHA -> engram ID (first one wins if multiple engrams reference same commit)
 68→    let mut commit_to_engram: HashMap<String, String> = HashMap::new();
 69→    for m in &manifests {
 70→        for sha in &m.git_commits {
 71→            // If range filter is set, only include commits in that range
 72→            if let Some(ref filter) = range_filter {
 73→                if !filter.contains(sha) {
 74→                    continue;
 75→                }
 76→            }
 77→            commit_to_engram
 78→                .entry(sha.clone())
 79→                .or_insert_with(|| m.id.as_str().to_string());
 80→        }
 81→    }
 82→
 83→    if commit_to_engram.is_empty() {
 84→        if args.range.is_some() {
 85→            println!("No engram-linked commits found in the specified range.");
 86→        } else {
 87→            println!("No engrams with linked commits found.");
 88→            println!(
 89→                "Hint: Commits are linked when using `engram record` or Claude Code auto-capture."
 90→            );
 91→        }
 92→        return Ok(());
 93→    }
 94→
 95→    let sig = repo
 96→        .signature()
 97→        .unwrap_or_else(|_| git2::Signature::now("engram", "engram@localhost").unwrap());
 98→
 99→    let mut annotated = 0;
100→    let mut skipped = 0;
101→
102→    for (sha, engram_id) in &commit_to_engram {
103→        let oid = git2::Oid::from_str(sha).context(format!("Invalid commit SHA: {sha}"))?;
104→
105→        // Check if note already exists
106→        let has_note = repo.find_note(Some(ENGRAM_NOTES_REF), oid).is_ok();
107→        if has_note && !args.force {
108→            skipped += 1;
109→            if args.dry_run {
110→                println!("  skip {}: already annotated (use --force)", &sha[..8]);
111→            }
112→            continue;
113→        }
114→
115→        // Read the full engram data
116→        let data = match storage.read(engram_id) {
117→            Ok(d) => d,
118→            Err(e) => {
119→                tracing::debug!("Cannot read engram {engram_id}: {e}");
120→                continue;
121→            }
122→        };
123→
124→        let note = format_note(&data);
125→
126→        if args.dry_run {
127→            let action = if has_note { "overwrite" } else { "annotate" };
128→            println!("  {action} {}:", &sha[..8.min(sha.len())]);
129→            for line in note.lines() {
130→                println!("    {line}");
131→            }
132→            annotated += 1;
133→            continue;
134→        }
135→
136→        // Remove existing note if force
137→        if has_note {
138→            let _ = repo.note_delete(oid, Some(ENGRAM_NOTES_REF), &sig, &sig);
139→        }
140→
141→        repo.note(&sig, &sig, Some(ENGRAM_NOTES_REF), oid, &note, args.force)
142→            .context(format!("Failed to create note on {sha}"))?;
143→        annotated += 1;
144→    }
145→
146→    if args.dry_run {
147→        println!(
148→            "\nWould annotate {} commit(s), skip {} (already annotated).",
149→            annotated, skipped
150→        );
151→    } else {
152→        println!("Annotated {} commit(s).", annotated);
153→        if skipped > 0 {
154→            println!("Skipped {skipped} (already annotated, use --force to overwrite).");
155→        }
156→        if annotated > 0 {
157→            println!("\nView with: git log --notes=engram");
158→            println!("Or use:    git loge");
159→        }
160→    }
161→
162→    Ok(())
163→}
