  1→use std::collections::HashMap;
  2→use std::io::Write;
  3→
  4→use anyhow::{Context, Result};
  5→use clap::Args;
  6→use engram_core::storage::{GitStorage, ListOptions};
  7→
  8→use crate::output::OutputFormat;
  9→
 10→#[derive(Args)]
 11→pub struct AuditArgs {
 12→    /// Git range to audit (e.g., "main..HEAD"). If omitted, audits all commits on current branch.
 13→    pub range: Option<String>,
 14→
 15→    /// Write report to a file instead of stdout
 16→    #[arg(short, long)]
 17→    pub output: Option<String>,
 18→
 19→    /// Report format: json, markdown, csv
 20→    #[arg(long, default_value = "markdown")]
 21→    pub report: ReportFormat,
 22→}
 23→
 24→#[derive(Debug, Clone, clap::ValueEnum)]
 25→pub enum ReportFormat {
 26→    Json,
 27→    Markdown,
 28→    Csv,
 29→}
 30→
 31→struct AuditEntry {
 32→    commit_sha: String,
 33→    commit_date: String,
 34→    commit_author: String,
 35→    commit_message: String,
 36→    engram_id: Option<String>,
 37→    agent: Option<String>,
 38→    model: Option<String>,
 39→    tokens: Option<u64>,
 40→    cost: Option<f64>,
 41→    dead_ends: Vec<String>,
 42→    decisions: Vec<String>,
 43→}
 44→
 45→pub fn run(args: &AuditArgs, _format: OutputFormat) -> Result<()> {
 46→    let storage = GitStorage::discover().context("Not inside a Git repository")?;
 47→
 48→    if !storage.is_initialized() {
 49→        anyhow::bail!("Engram is not initialized. Run `engram init` first.");
 50→    }
 51→
 52→    let repo = storage.repo();
 53→
 54→    // Build commit SHA -> engram ID map from all manifests
 55→    let manifests = storage
 56→        .list(&ListOptions::default())
 57→        .context("Failed to list engrams")?;
 58→
 59→    let mut commit_to_engram: HashMap<String, String> = HashMap::new();
 60→    for m in &manifests {
 61→        for sha in &m.git_commits {
 62→            commit_to_engram
 63→                .entry(sha.clone())
 64→                .or_insert_with(|| m.id.as_str().to_string());
 65→        }
 66→    }
 67→
 68→    // Also check for Engram-Id trailers in commit messages
 69→    let mut trailer_to_engram: HashMap<String, String> = HashMap::new();
 70→
 71→    // Walk commits
 72→    let mut revwalk = repo.revwalk().context("Cannot create revwalk")?;
 73→
 74→    if let Some(range) = &args.range {
 75→        let parts: Vec<&str> = range.split("..").collect();
 76→        if parts.len() != 2 {
 77→            anyhow::bail!("Invalid range format. Expected 'base..head' (e.g., 'main..HEAD').");
 78→        }
 79→        let head_obj = repo
 80→            .revparse_single(parts[1])
 81→            .context(format!("Cannot resolve '{}'", parts[1]))?;
 82→        let base_obj = repo
 83→            .revparse_single(parts[0])
 84→            .context(format!("Cannot resolve '{}'", parts[0]))?;
 85→        revwalk
 86→            .push(head_obj.id())
 87→            .context("Cannot push head to revwalk")?;
 88→        revwalk
 89→            .hide(base_obj.id())
 90→            .context("Cannot hide base in revwalk")?;
 91→    } else {
 92→        // Default: walk from HEAD
 93→        revwalk.push_head().context("Cannot push HEAD to revwalk")?;
 94→    }
 95→
 96→    revwalk.set_sorting(git2::Sort::TOPOLOGICAL | git2::Sort::TIME)?;
 97→
 98→    let mut entries = Vec::new();
 99→
100→    for oid_result in revwalk {
101→        let oid = oid_result.context("Revwalk error")?;
102→        let commit = repo.find_commit(oid).context("Cannot find commit")?;
103→        let sha = oid.to_string();
104→
105→        let message = commit.message().unwrap_or("").to_string();
106→        let summary = commit.summary().unwrap_or("").to_string();
107→        let author = commit.author().name().unwrap_or("unknown").to_string();
108→        let time = commit.time();
109→        let date = chrono::DateTime::from_timestamp(time.seconds(), 0)
110→            .map(|dt| dt.format("%Y-%m-%d %H:%M:%S").to_string())
111→            .unwrap_or_default();
112→
113→        // Find engram: first try direct commit linkage, then trailer
114→        let engram_id = commit_to_engram.get(&sha).cloned().or_else(|| {
115→            // Extract Engram-Id trailer from commit message
116→            for line in message.lines() {
117→                if let Some(id) = line.strip_prefix("Engram-Id: ") {
118→                    let id = id.trim().to_string();
119→                    trailer_to_engram
120→                        .entry(sha.clone())
121→                        .or_insert_with(|| id.clone());
122→                    return Some(id);
123→                }
124→            }
125→            None
126→        });
127→
128→        let mut entry = AuditEntry {
129→            commit_sha: sha,
130→            commit_date: date,
131→            commit_author: author,
132→            commit_message: summary,
133→            engram_id: engram_id.clone(),
134→            agent: None,
135→            model: None,
136→            tokens: None,
137→            cost: None,
138→            dead_ends: Vec::new(),
139→            decisions: Vec::new(),
140→        };
141→
142→        // Enrich with engram data if available
143→        if let Some(eid) = &engram_id {
144→            if let Ok(data) = storage.read(eid) {
145→                let m = &data.manifest;
146→                entry.agent = Some(m.agent.name.clone());
147→                entry.model = m.agent.model.clone();
148→                entry.tokens = Some(m.token_usage.total_tokens);
149→                entry.cost = Some(
150→                    m.token_usage
151→                        .effective_cost(m.agent.model.as_deref())
152→                        .unwrap_or(0.0),
153→                );
154→                entry.dead_ends = data
155→                    .intent
156→                    .dead_ends
157→                    .iter()
158→                    .map(|de| format!("{}: {}", de.approach, de.reason))
159→                    .collect();
160→                entry.decisions = data
161→                    .intent
162→                    .decisions
163→                    .iter()
164→                    .map(|d| format!("{}: {}", d.description, d.rationale))
165→                    .collect();
166→            }
167→        }
168→
169→        entries.push(entry);
170→    }
171→
172→    // Generate report
173→    let report = match args.report {
174→        ReportFormat::Json => render_json(&entries),
175→        ReportFormat::Markdown => render_markdown(&entries),
176→        ReportFormat::Csv => render_csv(&entries),
177→    };
178→
179→    // Output
180→    if let Some(path) = &args.output {
181→        let mut file =
182→            std::fs::File::create(path).context(format!("Cannot create output file: {path}"))?;
183→        file.write_all(report.as_bytes())
184→            .context("Failed to write report")?;
185→        let traced = entries.iter().filter(|e| e.engram_id.is_some()).count();
186→        let total = entries.len();
187→        println!("Audit report written to {path} ({traced}/{total} commits traced)",);
188→    } else {
189→        print!("{report}");
190→    }
191→
192→    Ok(())
193→}
194→
195→fn render_json(entries: &[AuditEntry]) -> String {
196→    let traced = entries.iter().filter(|e| e.engram_id.is_some()).count();
197→    let untraced = entries.len() - traced;
198→    let total_tokens: u64 = entries.iter().filter_map(|e| e.tokens).sum();
199→    let total_cost: f64 = entries.iter().filter_map(|e| e.cost).sum();
200→
201→    let json_entries: Vec<_> = entries
202→        .iter()
203→        .map(|e| {
204→            serde_json::json!({
205→                "commit": &e.commit_sha[..8.min(e.commit_sha.len())],
206→                "commit_full": e.commit_sha,
207→                "date": e.commit_date,
208→                "author": e.commit_author,
209→                "message": e.commit_message,
210→                "traced": e.engram_id.is_some(),
211→                "engram_id": e.engram_id.as_deref().map(|id| &id[..8.min(id.len())]),
212→                "agent": e.agent,
213→                "model": e.model,
214→                "tokens": e.tokens,
215→                "cost_usd": e.cost,
216→                "dead_ends": e.dead_ends,
217→                "decisions": e.decisions,
218→            })
219→        })
220→        .collect();
221→
222→    let output = serde_json::json!({
223→        "audit_report": {
224→            "total_commits": entries.len(),
225→            "traced_commits": traced,
226→            "untraced_commits": untraced,
227→            "coverage_pct": if entries.is_empty() { 0.0 } else { (traced as f64 / entries.len() as f64) * 100.0 },
228→            "total_tokens": total_tokens,
229→            "total_cost_usd": total_cost,
230→        },
231→        "entries": json_entries,
232→    });
233→
234→    serde_json::to_string_pretty(&output).unwrap_or_default()
235→}
236→
237→fn render_markdown(entries: &[AuditEntry]) -> String {
238→    let traced = entries.iter().filter(|e| e.engram_id.is_some()).count();
239→    let total = entries.len();
240→    let total_tokens: u64 = entries.iter().filter_map(|e| e.tokens).sum();
241→    let total_cost: f64 = entries.iter().filter_map(|e| e.cost).sum();
242→    let coverage = if total > 0 {
243→        (traced as f64 / total as f64) * 100.0
244→    } else {
245→        0.0
246→    };
247→
248→    let mut out = String::new();
249→
250→    // Header
251→    out.push_str("# Engram Audit Report\n\n");
252→    out.push_str(&format!(
253→        "| Metric | Value |\n|--------|-------|\n| Total commits | {} |\n| Traced commits | {} |\n| Untraced commits | {} |\n| Coverage | {:.1}% |\n| Total tokens | {} |\n| Total cost | ${:.2} |\n\n",
254→        total,
255→        traced,
256→        total - traced,
257→        coverage,
258→        total_tokens,
259→        total_cost
260→    ));
261→
262→    // Table
263→    out.push_str("## Commit Details\n\n");
264→    out.push_str("| Commit | Date | Author | Message | Traced | Agent | Tokens | Cost |\n");
265→    out.push_str("|--------|------|--------|---------|--------|-------|--------|------|\n");
266→
267→    for e in entries {
268→        let short_sha = &e.commit_sha[..8.min(e.commit_sha.len())];
269→        let traced_mark = if e.engram_id.is_some() {
270→            "yes"
271→        } else {
272→            "**NO**"
273→        };
274→        let agent = e.agent.as_deref().unwrap_or("-");
275→        let tokens = e
276→            .tokens
277→            .map(|t| t.to_string())
278→            .unwrap_or_else(|| "-".to_string());
279→        let cost = e
280→            .cost
281→            .map(|c| format!("${c:.2}"))
282→            .unwrap_or_else(|| "-".to_string());
283→        let msg = if e.commit_message.len() > 50 {
284→            format!("{}...", &e.commit_message[..47])
285→        } else {
286→            e.commit_message.clone()
287→        };
288→
289→        out.push_str(&format!(
290→            "| {short_sha} | {} | {} | {msg} | {traced_mark} | {agent} | {tokens} | {cost} |\n",
291→            e.commit_date, e.commit_author
292→        ));
293→    }
294→
295→    // Untraced section
296→    let untraced: Vec<_> = entries.iter().filter(|e| e.engram_id.is_none()).collect();
297→    if !untraced.is_empty() {
298→        out.push_str("\n## Untraced Commits\n\n");
299→        out.push_str("These commits have no associated AI reasoning chain:\n\n");
300→        for e in &untraced {
301→            let short_sha = &e.commit_sha[..8.min(e.commit_sha.len())];
302→            out.push_str(&format!(
303→                "- `{short_sha}` {} — {}\n",
304→                e.commit_date, e.commit_message
305→            ));
306→        }
307→    }
308→
309→    out
310→}
311→
312→fn render_csv(entries: &[AuditEntry]) -> String {
313→    let mut out = String::new();
314→    out.push_str("commit,date,author,message,traced,engram_id,agent,model,tokens,cost_usd\n");
315→
316→    for e in entries {
317→        let short_sha = &e.commit_sha[..8.min(e.commit_sha.len())];
318→        let engram_short = e
319→            .engram_id
320→            .as_deref()
321→            .map(|id| &id[..8.min(id.len())])
322→            .unwrap_or("");
323→        let agent = e.agent.as_deref().unwrap_or("");
324→        let model = e.model.as_deref().unwrap_or("");
325→        let tokens = e.tokens.map(|t| t.to_string()).unwrap_or_default();
326→        let cost = e.cost.map(|c| format!("{c:.4}")).unwrap_or_default();
327→        // Escape message for CSV
328→        let msg = e.commit_message.replace('"', "\"\"");
329→
330→        out.push_str(&format!(
331→            "{short_sha},{},{},\"{msg}\",{},{engram_short},{agent},{model},{tokens},{cost}\n",
332→            e.commit_date,
333→            e.commit_author,
334→            e.engram_id.is_some(),
335→        ));
336→    }
337→
338→    out
339→}
