  1→use std::path::PathBuf;
  2→
  3→use anyhow::{Context, Result};
  4→use clap::Args;
  5→
  6→use engram_core::config::GlobalConfig;
  7→use engram_core::storage::GitStorage;
  8→use engram_query::{SearchEngine, SearchResult};
  9→
 10→use crate::output::OutputFormat;
 11→
 12→#[derive(Args)]
 13→pub struct SearchArgs {
 14→    /// Search query (free-text, searches intent, transcript, file paths, dead ends)
 15→    pub query: String,
 16→
 17→    /// Maximum number of results
 18→    #[arg(short = 'n', long, default_value = "10")]
 19→    pub limit: usize,
 20→
 21→    /// Search across all registered repositories
 22→    #[arg(long)]
 23→    pub global: bool,
 24→
 25→    /// Search specific repositories (comma-separated paths)
 26→    #[arg(long, value_delimiter = ',')]
 27→    pub repos: Vec<PathBuf>,
 28→}
 29→
 30→pub fn run(args: &SearchArgs, format: OutputFormat) -> Result<()> {
 31→    if args.global || !args.repos.is_empty() {
 32→        return run_multi_repo(args, format);
 33→    }
 34→
 35→    let storage = GitStorage::discover().context("Not in a Git repository with engram")?;
 36→    let engine = SearchEngine::open(&storage)?;
 37→
 38→    let results = engine.search(&storage, &args.query, args.limit)?;
 39→
 40→    if results.is_empty() {
 41→        eprintln!("No results found for: {}", args.query);
 42→        return Ok(());
 43→    }
 44→
 45→    match format {
 46→        OutputFormat::Json => {
 47→            let manifests: Vec<_> = results.iter().map(|r| &r.manifest).collect();
 48→            println!("{}", serde_json::to_string_pretty(&manifests)?);
 49→        }
 50→        OutputFormat::Text | OutputFormat::Markdown => {
 51→            eprintln!("Found {} result(s) for: {}\n", results.len(), args.query);
 52→            for result in &results {
 53→                let m = &result.manifest;
 54→                let short_id = &m.id.as_str()[..8];
 55→                let summary = m.summary.as_deref().unwrap_or("(no summary)");
 56→                let score = result.score;
 57→                println!("{short_id}  {summary}  (score: {score:.2})");
 58→            }
 59→        }
 60→    }
 61→
 62→    Ok(())
 63→}
 64→
 65→fn run_multi_repo(args: &SearchArgs, format: OutputFormat) -> Result<()> {
 66→    let repo_paths: Vec<PathBuf> = if !args.repos.is_empty() {
 67→        args.repos.clone()
 68→    } else {
 69→        let config = GlobalConfig::load().context("Failed to load global config")?;
 70→        if config.repos.is_empty() {
 71→            anyhow::bail!(
 72→                "No repositories registered. Run `engram init` in your repos, or use --repos."
 73→            );
 74→        }
 75→        config.repos
 76→    };
 77→
 78→    let mut all_results: Vec<(String, SearchResult)> = Vec::new();
 79→
 80→    for repo_path in &repo_paths {
 81→        let storage = match GitStorage::open(repo_path) {
 82→            Ok(s) if s.is_initialized() => s,
 83→            _ => {
 84→                tracing::debug!("Skipping {}: not initialized", repo_path.display());
 85→                continue;
 86→            }
 87→        };
 88→
 89→        let engine = match SearchEngine::open(&storage) {
 90→            Ok(e) => e,
 91→            Err(e) => {
 92→                tracing::debug!("Skipping {}: {}", repo_path.display(), e);
 93→                continue;
 94→            }
 95→        };
 96→
 97→        match engine.search(&storage, &args.query, args.limit) {
 98→            Ok(results) => {
 99→                let label = repo_path
100→                    .file_name()
101→                    .map(|n| n.to_string_lossy().to_string())
102→                    .unwrap_or_else(|| repo_path.display().to_string());
103→                for r in results {
104→                    all_results.push((label.clone(), r));
105→                }
106→            }
107→            Err(e) => {
108→                tracing::debug!("Search failed in {}: {}", repo_path.display(), e);
109→            }
110→        }
111→    }
112→
113→    // Sort by score descending
114→    all_results.sort_by(|a, b| {
115→        b.1.score
116→            .partial_cmp(&a.1.score)
117→            .unwrap_or(std::cmp::Ordering::Equal)
118→    });
119→    all_results.truncate(args.limit);
120→
121→    if all_results.is_empty() {
122→        eprintln!(
123→            "No results found for '{}' across {} repositories.",
124→            args.query,
125→            repo_paths.len()
126→        );
127→        return Ok(());
128→    }
129→
130→    match format {
131→        OutputFormat::Json => {
132→            let entries: Vec<_> = all_results
133→                .iter()
134→                .map(|(repo, r)| {
135→                    serde_json::json!({
136→                        "repo": repo,
137→                        "manifest": r.manifest,
138→                        "score": r.score,
139→                    })
140→                })
141→                .collect();
142→            println!("{}", serde_json::to_string_pretty(&entries)?);
143→        }
144→        OutputFormat::Text | OutputFormat::Markdown => {
145→            eprintln!(
146→                "Found {} result(s) for '{}' across {} repositories:\n",
147→                all_results.len(),
148→                args.query,
149→                repo_paths.len()
150→            );
151→            for (repo, result) in &all_results {
152→                let m = &result.manifest;
153→                let short_id = &m.id.as_str()[..8];
154→                let summary = m.summary.as_deref().unwrap_or("(no summary)");
155→                let score = result.score;
