  3→/// Notes ref namespace used for engram annotations on commits.
  4→pub const ENGRAM_NOTES_REF: &str = "refs/notes/engram";
  5→
  6→/// Format an engram as a git note string for attaching to a commit.
  7→pub fn format_note(data: &EngramData) -> String {
  8→    let m = &data.manifest;
  9→    let agent = &m.agent.name;
 10→    let model = m.agent.model.as_deref().unwrap_or("unknown");
 11→    let tokens = m.token_usage.total_tokens;
 12→    let cost = m
 13→        .token_usage
 14→        .effective_cost(m.agent.model.as_deref())
 15→        .map(|c| format!("${c:.2}"))
 16→        .unwrap_or_else(|| "-".to_string());
 17→
 18→    let mut out = format!("[{agent}/{model}] {cost} {tokens}tok\n");
 19→
 20→    // Intent
 21→    let request = &data.intent.original_request;
 22→    // Truncate long requests for the note
 23→    let display_request = if request.len() > 120 {
 24→        format!("{}...", &request[..117])
 25→    } else {
 26→        request.clone()
 27→    };
 28→    out.push_str(&format!("Intent: \"{display_request}\"\n"));
 29→
 30→    // Summary
 31→    if let Some(summary) = data.intent.summary.as_deref().or(m.summary.as_deref()) {
 32→        let display_summary = if summary.len() > 200 {
 33→            format!("{}...", &summary[..197])
 34→        } else {
 35→            summary.to_string()
 36→        };
 37→        out.push_str(&format!("Summary: {display_summary}\n"));
 38→    }
 39→
 40→    // Dead ends
 41→    if !data.intent.dead_ends.is_empty() {
 42→        out.push_str("Dead ends:\n");
 43→        for de in &data.intent.dead_ends {
 44→            out.push_str(&format!("  - {}: {}\n", de.approach, de.reason));
 45→        }
 46→    }
 47→
 48→    // Decisions
 49→    if !data.intent.decisions.is_empty() {
 50→        out.push_str("Decisions:\n");
 51→        for d in &data.intent.decisions {
 52→            out.push_str(&format!("  - {}: {}\n", d.description, d.rationale));
 53→        }
 54→    }
 55→
 56→    // File changes
 57→    if !data.operations.file_changes.is_empty() {
 58→        let files: Vec<String> = data
 59→            .operations
 60→            .file_changes
 61→            .iter()
 62→            .map(|fc| {
 63→                let prefix = match &fc.change_type {
 64→                    FileChangeType::Created => "+",
 65→                    FileChangeType::Modified => "~",
 66→                    FileChangeType::Deleted => "-",
 67→                    FileChangeType::Renamed { .. } => "→",
 68→                };
 69→                // Show just the filename for brevity
 70→                let name = fc.path.rsplit('/').next().unwrap_or(&fc.path);
 71→                format!("{prefix}{name}")
 72→            })
 73→            .collect();
 74→        out.push_str(&format!("Files: {}\n", files.join(" ")));
 75→    }
 76→
 77→    out
 78→}
