  6→/// A single line of the transcript.jsonl file.
  7→#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
  8→pub struct TranscriptEntry {
  9→    pub timestamp: DateTime<Utc>,
 10→    pub role: Role,
 11→    pub content: TranscriptContent,
 12→    #[serde(default, skip_serializing_if = "Option::is_none")]
 13→    pub token_count: Option<u64>,
 14→}
 15→
 16→#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
 17→#[serde(rename_all = "snake_case")]
 18→pub enum Role {
 19→    User,
 20→    Assistant,
 21→    System,
 22→    Tool,
 23→}
 24→
 25→#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
 26→#[serde(tag = "type")]
 27→pub enum TranscriptContent {
 28→    #[serde(rename = "text")]
 29→    Text { text: String },
 30→    #[serde(rename = "tool_use")]
 31→    ToolUse {
 32→        tool_name: String,
 33→        tool_id: String,
 34→        input: serde_json::Value,
 35→    },
 36→    #[serde(rename = "tool_result")]
 37→    ToolResult {
 38→        tool_id: String,
 39→        output: String,
 40→        is_error: bool,
 41→    },
 42→    #[serde(rename = "thinking")]
 43→    Thinking { text: String },
 44→}
 45→
 46→/// The full transcript, serialized as JSONL.
 47→#[derive(Debug, Clone, Default, PartialEq)]
 48→pub struct Transcript {
 49→    pub entries: Vec<TranscriptEntry>,
 50→}
 51→
 52→impl Transcript {
 53→    /// Serialize to JSONL bytes (one JSON object per line).
 54→    pub fn to_jsonl(&self) -> Result<Vec<u8>, CoreError> {
 55→        let mut buf = Vec::new();
 56→        for entry in &self.entries {
 57→            serde_json::to_writer(&mut buf, entry)?;
 58→            buf.push(b'\n');
 59→        }
 60→        Ok(buf)
 61→    }
 62→
 63→    /// Deserialize from JSONL bytes.
 64→    pub fn from_jsonl(data: &[u8]) -> Result<Self, CoreError> {
 65→        let text = std::str::from_utf8(data).map_err(|e| CoreError::Parse(e.to_string()))?;
 66→        let mut entries = Vec::new();
 67→        for line in text.lines() {
 68→            if line.trim().is_empty() {
 69→                continue;
 70→            }
 71→            let entry: TranscriptEntry =
 72→                serde_json::from_str(line).map_err(CoreError::InvalidManifest)?;
 73→            entries.push(entry);
 74→        }
 75→        Ok(Transcript { entries })
 76→    }
 77→}
