 11→use tower_http::cors::CorsLayer;
 12→
 13→use engram_core::storage::{GitStorage, ListOptions};
 14→use engram_query::SearchEngine;
 15→
 16→const INDEX_HTML: &str = include_str!("../static/index.html");
 17→
 18→struct AppState {
 19→    repo_path: PathBuf,
 20→}
 21→
 22→fn open_storage(state: &AppState) -> Result<GitStorage, StatusCode> {
 23→    GitStorage::open(&state.repo_path).map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)
 24→}
 25→
 26→/// Build the axum router for the dashboard.
 27→pub fn build_router(repo_path: &Path) -> Router {
 28→    let state = Arc::new(AppState {
 29→        repo_path: repo_path.to_path_buf(),
 30→    });
 31→
 32→    Router::new()
 33→        .route("/", get(index_handler))
 34→        .route("/api/engrams", get(list_engrams))
 35→        .route("/api/engrams/{id}", get(show_engram))
 36→        .route("/api/stats", get(stats_handler))
 37→        .route("/api/stats/trend", get(stats_trend))
 38→        .route("/api/stats/by-file", get(stats_by_file))
 39→        .route("/api/stats/by-agent", get(stats_by_agent))
 40→        .route("/api/search", get(search_handler))
 41→        .layer(CorsLayer::permissive())
 42→        .with_state(state)
 43→}
 44→
 45→/// Start the dashboard server.
 46→pub async fn serve(repo_path: &Path, port: u16) -> std::io::Result<()> {
 47→    let app = build_router(repo_path);
 48→    let listener = tokio::net::TcpListener::bind(format!("0.0.0.0:{port}")).await?;
 49→    tracing::info!("Dashboard listening on http://localhost:{port}");
 50→    axum::serve(listener, app).await
 51→}
