 57→#[derive(Deserialize)]
 58→struct ListParams {
 59→    limit: Option<usize>,
 60→    agent: Option<String>,
 61→}
 62→
 63→async fn list_engrams(
 64→    State(state): State<Arc<AppState>>,
 65→    Query(params): Query<ListParams>,
 66→) -> impl IntoResponse {
 67→    let storage = open_storage(&state)?;
 68→    let opts = ListOptions {
 69→        limit: Some(params.limit.unwrap_or(50)),
 70→        agent_filter: params.agent,
 71→    };
 72→    let manifests = storage
 73→        .list(&opts)
 74→        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
 75→
 76→    let entries: Vec<_> = manifests
 77→        .iter()
 78→        .map(|m| {
 79→            serde_json::json!({
 80→                "id": m.id.as_str(),
 81→                "short_id": &m.id.as_str()[..8.min(m.id.as_str().len())],
 82→                "created_at": m.created_at.to_rfc3339(),
 83→                "agent": m.agent.name,
 84→                "model": m.agent.model,
 85→                "summary": m.summary,
 86→                "tokens": m.token_usage.total_tokens,
 87→                "cost_usd": m.token_usage.effective_cost(m.agent.model.as_deref()),
 88→                "capture_mode": format!("{:?}", m.capture_mode),
 89→                "files_changed": m.git_commits.len(),
 90→            })
 91→        })
 92→        .collect();
 93→
 94→    Ok::<_, StatusCode>(axum::Json(serde_json::json!({
 95→        "engrams": entries,
 96→        "total": entries.len(),
 97→    })))
 98→}
