100→async fn show_engram(
101→    State(state): State<Arc<AppState>>,
102→    axum::extract::Path(id): axum::extract::Path<String>,
103→) -> impl IntoResponse {
104→    let storage = open_storage(&state)?;
105→    let resolved = storage.resolve(&id).map_err(|_| StatusCode::NOT_FOUND)?;
106→    let data = storage.read(&resolved).map_err(|_| StatusCode::NOT_FOUND)?;
107→
108→    let m = &data.manifest;
109→    Ok::<_, StatusCode>(axum::Json(serde_json::json!({
110→        "id": m.id.as_str(),
111→        "created_at": m.created_at.to_rfc3339(),
112→        "agent": m.agent.name,
113→        "model": m.agent.model,
114→        "summary": m.summary,
115→        "tokens": m.token_usage.total_tokens,
116→        "cost_usd": m.token_usage.effective_cost(m.agent.model.as_deref()),
117→        "capture_mode": format!("{:?}", m.capture_mode),
118→        "git_commits": m.git_commits,
119→        "intent": {
120→            "request": data.intent.original_request,
121→            "goal": data.intent.interpreted_goal,
122→            "summary": data.intent.summary,
123→        },
124→        "file_changes": data.operations.file_changes.iter().map(|fc| {
125→            serde_json::json!({
126→                "path": fc.path,
127→                "change_type": format!("{:?}", fc.change_type).to_lowercase(),
128→                "lines_added": fc.lines_added,
129→                "lines_removed": fc.lines_removed,
130→            })
131→        }).collect::<Vec<_>>(),
132→        "dead_ends": data.intent.dead_ends.iter().map(|de| {
133→            serde_json::json!({ "approach": de.approach, "reason": de.reason })
134→        }).collect::<Vec<_>>(),
135→        "decisions": data.intent.decisions.iter().map(|d| {
136→            serde_json::json!({ "description": d.description, "rationale": d.rationale })
137→        }).collect::<Vec<_>>(),
138→    })))
139→}
