141→async fn stats_handler(State(state): State<Arc<AppState>>) -> impl IntoResponse {
142→    let storage = open_storage(&state)?;
143→    let manifests = storage
144→        .list(&ListOptions::default())
145→        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
146→
147→    let mut total_tokens: u64 = 0;
148→    let mut total_cost: f64 = 0.0;
149→    let mut by_agent: BTreeMap<String, (usize, u64, f64)> = BTreeMap::new();
150→    let mut by_mode: BTreeMap<String, usize> = BTreeMap::new();
151→
152→    for m in &manifests {
153→        let cost = m
154→            .token_usage
155→            .effective_cost(m.agent.model.as_deref())
156→            .unwrap_or(0.0);
157→        total_tokens += m.token_usage.total_tokens;
158→        total_cost += cost;
159→
160→        let entry = by_agent.entry(m.agent.name.clone()).or_default();
161→        entry.0 += 1;
162→        entry.1 += m.token_usage.total_tokens;
163→        entry.2 += cost;
164→
165→        *by_mode.entry(format!("{:?}", m.capture_mode)).or_default() += 1;
166→    }
167→
168→    Ok::<_, StatusCode>(axum::Json(serde_json::json!({
169→        "total_engrams": manifests.len(),
170→        "total_tokens": total_tokens,
171→        "total_cost_usd": total_cost,
172→        "earliest": manifests.last().map(|m| m.created_at.to_rfc3339()),
173→        "latest": manifests.first().map(|m| m.created_at.to_rfc3339()),
174→        "by_agent": by_agent.iter().map(|(name, (count, tokens, cost))| {
175→            serde_json::json!({ "agent": name, "count": count, "tokens": tokens, "cost_usd": cost })
176→        }).collect::<Vec<_>>(),
177→        "by_capture_mode": by_mode,
178→    })))
179→}
180→
181→async fn stats_trend(State(state): State<Arc<AppState>>) -> impl IntoResponse {
182→    let storage = open_storage(&state)?;
183→    let manifests = storage
184→        .list(&ListOptions::default())
185→        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
186→
187→    let cutoff = chrono::Utc::now() - chrono::Duration::days(30);
188→    let mut by_date: BTreeMap<chrono::NaiveDate, (usize, u64, f64)> = BTreeMap::new();
189→
190→    for m in &manifests {
191→        if m.created_at < cutoff {
192→            continue;
193→        }
194→        let cost = m
195→            .token_usage
196→            .effective_cost(m.agent.model.as_deref())
197→            .unwrap_or(0.0);
198→        let date = m.created_at.date_naive();
199→        let entry = by_date.entry(date).or_default();
200→        entry.0 += 1;
201→        entry.1 += m.token_usage.total_tokens;
202→        entry.2 += cost;
203→    }
204→
205→    let entries: Vec<_> = by_date
206→        .iter()
207→        .map(|(date, (sessions, tokens, cost))| {
208→            serde_json::json!({
209→                "date": date.to_string(),
210→                "sessions": sessions,
211→                "tokens": tokens,
212→                "cost_usd": cost,
213→            })
214→        })
215→        .collect();
216→
217→    Ok::<_, StatusCode>(axum::Json(serde_json::json!({ "trend": entries })))
218→}
