220→#[derive(Deserialize)]
221→struct TopParams {
222→    top: Option<usize>,
223→}
224→
225→async fn stats_by_file(
226→    State(state): State<Arc<AppState>>,
227→    Query(params): Query<TopParams>,
228→) -> impl IntoResponse {
229→    let storage = open_storage(&state)?;
230→    let manifests = storage
231→        .list(&ListOptions::default())
232→        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
233→    let top = params.top.unwrap_or(10);
234→
235→    let mut by_file: BTreeMap<String, (usize, u64, f64)> = BTreeMap::new();
236→
237→    for m in &manifests {
238→        if let Ok(data) = storage.read(m.id.as_str()) {
239→            let file_count = data.operations.file_changes.len();
240→            if file_count == 0 {
241→                continue;
242→            }
243→            let per_file_tokens = m.token_usage.total_tokens / file_count as u64;
244→            let per_file_cost = m
245→                .token_usage
246→                .effective_cost(m.agent.model.as_deref())
247→                .unwrap_or(0.0)
248→                / file_count as f64;
249→
250→            for fc in &data.operations.file_changes {
251→                let entry = by_file.entry(fc.path.clone()).or_default();
252→                entry.0 += 1;
253→                entry.1 += per_file_tokens;
254→                entry.2 += per_file_cost;
255→            }
256→        }
257→    }
258→
259→    let mut sorted: Vec<_> = by_file.into_iter().collect();
260→    sorted.sort_by(|a, b| {
261→        b.1 .2
262→            .partial_cmp(&a.1 .2)
263→            .unwrap_or(std::cmp::Ordering::Equal)
264→    });
265→    sorted.truncate(top);
266→
267→    let entries: Vec<_> = sorted
268→        .iter()
269→        .map(|(path, (sessions, tokens, cost))| {
270→            serde_json::json!({
271→                "file": path,
272→                "sessions": sessions,
273→                "tokens": tokens,
274→                "cost_usd": cost,
275→            })
276→        })
277→        .collect();
278→
279→    Ok::<_, StatusCode>(axum::Json(serde_json::json!({ "files": entries })))
280→}
