316→#[derive(Deserialize)]
317→struct SearchParams {
318→    q: String,
319→    limit: Option<usize>,
320→}
321→
322→async fn search_handler(
323→    State(state): State<Arc<AppState>>,
324→    Query(params): Query<SearchParams>,
325→) -> impl IntoResponse {
326→    let storage = open_storage(&state)?;
327→    let engine = SearchEngine::open(&storage).map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
328→
329→    let results = engine
330→        .search(&storage, &params.q, params.limit.unwrap_or(20))
331→        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
332→
333→    let entries: Vec<_> = results
334→        .iter()
335→        .map(|r| {
336→            let m = &r.manifest;
337→            serde_json::json!({
338→                "id": m.id.as_str(),
339→                "short_id": &m.id.as_str()[..8.min(m.id.as_str().len())],
340→                "summary": m.summary,
341→                "agent": m.agent.name,
342→                "model": m.agent.model,
343→                "score": r.score,
344→                "created_at": m.created_at.to_rfc3339(),
345→                "tokens": m.token_usage.total_tokens,
346→                "cost_usd": m.token_usage.effective_cost(m.agent.model.as_deref()),
347→            })
348→        })
349→        .collect();
350→
351→    Ok::<_, StatusCode>(axum::Json(serde_json::json!({
352→        "query": params.q,
353→        "results": entries,
354→        "total": entries.len(),
355→    })))
356→}
