 88→async function loadStats() {
 89→  const data = await fetchJSON('/api/stats');
 90→  const el = document.getElementById('stats-section');
 91→  const cost = data.total_cost_usd != null ? `$${data.total_cost_usd.toFixed(2)}` : '$0.00';
 92→  el.innerHTML = `
 93→    <div class="stat-card"><div class="label">Total Engrams</div><div class="value">${data.total_engrams}</div></div>
 94→    <div class="stat-card"><div class="label">Total Tokens</div><div class="value">${(data.total_tokens || 0).toLocaleString()}</div></div>
 95→    <div class="stat-card"><div class="label">Total Cost</div><div class="value cost">${cost}</div></div>
 96→    <div class="stat-card"><div class="label">Agents</div><div class="value">${(data.by_agent || []).length}</div></div>
 97→  `;
 98→}
