100→async function loadEngrams(query) {
101→  const url = query ? `/api/search?q=${encodeURIComponent(query)}` : '/api/engrams?limit=50';
102→  const data = await fetchJSON(url);
103→  const items = query ? data.results : data.engrams;
104→  const el = document.getElementById('content');
105→
106→  if (!items || items.length === 0) {
107→    el.innerHTML = '<div class="empty">No engrams found.</div>';
108→    return;
109→  }
110→
111→  el.innerHTML = '<div class="engram-list">' + items.map(e => `
112→    <div class="engram-item" onclick="showDetail('${e.id}')">
113→      <div class="header">
114→        <span class="id">${e.short_id || e.id.slice(0, 8)}</span>
115→        <span class="date">${new Date(e.created_at).toLocaleDateString()}</span>
116→      </div>
117→      <div class="summary">${e.summary || '(no summary)'}</div>
118→      <div class="meta">
119→        <span class="badge agent">${e.agent}</span>
120→        ${e.model ? `<span>${e.model}</span>` : ''}
121→        <span>${(e.tokens || 0).toLocaleString()} tokens</span>
122→        <span class="badge cost">$${(e.cost_usd || 0).toFixed(2)}</span>
123→        ${e.score != null ? `<span>score: ${e.score.toFixed(2)}</span>` : ''}
124→      </div>
125→    </div>
126→  `).join('') + '</div>';
127→}
