129→async function showDetail(id) {
130→  currentView = 'detail';
131→  const data = await fetchJSON(`/api/engrams/${id}`);
132→  const el = document.getElementById('content');
133→  const cost = data.cost_usd != null ? `$${data.cost_usd.toFixed(2)}` : 'N/A';
134→
135→  let html = `<button class="back-btn" onclick="backToList()">&larr; Back</button>`;
136→  html += `<div class="detail-panel">`;
137→  html += `<h2>${data.summary || data.intent?.request || '(no summary)'}</h2>`;
138→  html += `<div class="section"><h3>Details</h3>`;
139→  html += `<p><strong>ID:</strong> <code>${data.id}</code></p>`;
