  1→use std::io::Read as _;
  2→use std::path::PathBuf;
  3→
  4→use anyhow::{Context, Result};
  5→use clap::Args;
  6→use engram_capture::import::claude_code::ClaudeCodeImporter;
  7→use engram_core::config::EngramConfig;
  8→use engram_core::hooks;
  9→use engram_core::hooks::ActiveSession;
 10→use engram_core::model::AgentInfo;
 11→use engram_core::storage::GitStorage;
 12→use engram_query::search::SearchEngine;
 13→
 14→#[derive(Args)]
 15→pub struct HookHandlerArgs {
 16→    /// The hook name (prepare-commit-msg, post-commit, pre-push)
 17→    pub hook_name: String,
 18→
 19→    /// Extra arguments passed by git to the hook
 20→    #[arg(trailing_var_arg = true)]
 21→    pub args: Vec<String>,
 22→}
 23→
 24→pub fn run(args: &HookHandlerArgs) -> Result<()> {
 25→    // Find the git dir by discovering the repo
 26→    let storage = GitStorage::discover().context("Not inside a Git repository")?;
 27→    let git_dir = storage.repo().path().to_path_buf();
 28→
 29→    match args.hook_name.as_str() {
 30→        "prepare-commit-msg" => {
 31→            // Auto-capture: if enabled and no active session, import current Claude Code session
 32→            maybe_auto_capture(&storage, &git_dir);
 33→
 34→            let msg_file = args
 35→                .args
 36→                .first()
 37→                .map(PathBuf::from)
 38→                .context("prepare-commit-msg: missing message file argument")?;
 39→            hooks::handle_prepare_commit_msg(&msg_file, &git_dir)?;
 40→        }
 41→        "post-commit" => {
 42→            hooks::handle_post_commit(&git_dir)?;
 43→
 44→            // Auto-capture cleanup: if session was auto-created, clean it up
 45→            maybe_auto_capture_cleanup(&storage, &git_dir);
 46→        }
 47→        "pre-push" => {
 48→            maybe_auto_push(&storage);
 49→        }
 50→        "session-end" => {
 51→            handle_session_end(&storage);
 52→        }
 53→        other => {
 54→            tracing::debug!("Unknown hook: {other}, ignoring");
 55→        }
 56→    }
 57→
 58→    Ok(())
 59→}
 60→
 61→/// Handle Claude Code's `SessionEnd` hook.
 62→///
 63→/// Reads JSON from stdin (provided by Claude Code), extracts the `transcript_path`,
 64→/// and imports the session as an engram. All errors are logged at debug level and
 65→/// silently ignored so we never interfere with the user's workflow.
 66→fn handle_session_end(storage: &GitStorage) {
 67→    let mut input = String::new();
 68→    if std::io::stdin().read_to_string(&mut input).is_err() {
 69→        tracing::debug!("session-end: failed to read stdin");
 70→        return;
 71→    }
 72→
 73→    let json: serde_json::Value = match serde_json::from_str(&input) {
 74→        Ok(v) => v,
 75→        Err(e) => {
 76→            tracing::debug!("session-end: failed to parse JSON: {e}");
 77→            return;
 78→        }
 79→    };
 80→
 81→    let transcript_path = match json.get("transcript_path").and_then(|v| v.as_str()) {
 82→        Some(p) => std::path::PathBuf::from(p),
 83→        None => {
 84→            tracing::debug!("session-end: no transcript_path in input");
 85→            return;
 86→        }
 87→    };
 88→
 89→    if !transcript_path.exists() {
 90→        tracing::debug!(
 91→            "session-end: transcript file does not exist: {}",
 92→            transcript_path.display()
 93→        );
 94→        return;
 95→    }
 96→
 97→    let data = match ClaudeCodeImporter::import_session(&transcript_path) {
 98→        Ok(d) => d,
 99→        Err(e) => {
100→            tracing::debug!("session-end: failed to import session: {e}");
101→            return;
102→        }
103→    };
104→
105→    // Check for duplicates via source_hash
106→    if let Some(existing_id) = data
107→        .manifest
108→        .source_hash
109→        .as_deref()
110→        .and_then(|h| storage.find_by_source_hash(h))
111→    {
112→        tracing::debug!(
113→            "session-end: already imported as {}",
114→            &existing_id.as_str()[..8]
115→        );
116→        return;
117→    }
118→
119→    let id = data.manifest.id.clone();
120→    match storage.create(&data) {
121→        Ok(_) => {
122→            // Best-effort index update
123→            if let Ok(engine) = SearchEngine::open(storage) {
124→                let _ = engine.index_engram(&data);
125→            }
126→            tracing::debug!("session-end: imported engram {}", &id.as_str()[..8]);
127→
128→            // Best-effort: annotate commits that reference this engram
129→            auto_annotate_commits(storage, &data);
130→        }
131→        Err(e) => {
132→            tracing::debug!("session-end: failed to store engram: {e}");
133→        }
134→    }
135→}
136→
137→/// Scan recent commits for Engram-Id trailers matching the given engram,
138→/// and attach git notes with rich reasoning metadata.
139→fn auto_annotate_commits(storage: &GitStorage, data: &engram_core::model::EngramData) {
140→    use engram_core::notes::{format_note, ENGRAM_NOTES_REF};
141→
142→    let repo = storage.repo();
143→    let engram_id_str = data.manifest.id.as_str().to_string();
144→
145→    // Walk recent commits looking for Engram-Id trailers
146→    let head = match repo.head().and_then(|h| h.peel_to_commit()) {
147→        Ok(c) => c,
148→        Err(_) => return,
149→    };
150→
151→    let sig = repo
152→        .signature()
153→        .unwrap_or_else(|_| git2::Signature::now("engram", "engram@localhost").unwrap());
154→
155→    let mut revwalk = match repo.revwalk() {
156→        Ok(r) => r,
157→        Err(_) => return,
158→    };
159→    if revwalk.push(head.id()).is_err() {
160→        return;
161→    }
162→
163→    let note = format_note(data);
164→    let mut annotated = 0;
165→
166→    for oid_result in revwalk.take(50) {
167→        let oid = match oid_result {
168→            Ok(o) => o,
169→            Err(_) => break,
170→        };
171→        let commit = match repo.find_commit(oid) {
172→            Ok(c) => c,
173→            Err(_) => continue,
174→        };
175→
176→        if let Some(message) = commit.message() {
177→            for line in message.lines() {
178→                if let Some(trailer_id) = line.strip_prefix("Engram-Id: ") {
179→                    if trailer_id.trim() == engram_id_str {
180→                        // Skip if already annotated
181→                        if repo.find_note(Some(ENGRAM_NOTES_REF), oid).is_ok() {
182→                            continue;
183→                        }
184→                        if repo
185→                            .note(&sig, &sig, Some(ENGRAM_NOTES_REF), oid, &note, false)
186→                            .is_ok()
187→                        {
188→                            annotated += 1;
189→                        }
190→                    }
191→                }
192→            }
193→        }
194→    }
195→
196→    if annotated > 0 {
197→        tracing::debug!("session-end: annotated {annotated} commit(s) with engram notes");
198→    }
199→}
200→
201→/// If auto_capture is enabled and no active session exists, discover and import
202→/// the most recent Claude Code session, then create a temporary ActiveSession
203→/// so the prepare-commit-msg handler can inject trailers.
204→fn maybe_auto_capture(storage: &GitStorage, git_dir: &std::path::Path) {
205→    // Don't interfere with an existing session (e.g. from `engram record`)
206→    if ActiveSession::load(git_dir).is_some() {
207→        return;
208→    }
209→
210→    let config = match load_config(storage) {
211→        Some(c) => c,
212→        None => return,
213→    };
214→
215→    if !config.auto_capture {
216→        return;
217→    }
218→
219→    let workdir = match storage.workdir() {
220→        Some(w) => w.to_path_buf(),
221→        None => return,
222→    };
223→
224→    // Discover Claude Code session files for this project
225→    let session_files = match ClaudeCodeImporter::discover_sessions(&workdir) {
226→        Ok(files) => files,
227→        Err(e) => {
228→            tracing::debug!("Auto-capture: failed to discover sessions: {e}");
229→            return;
230→        }
231→    };
232→
233→    if session_files.is_empty() {
234→        tracing::debug!("Auto-capture: no Claude Code sessions found");
235→        return;
236→    }
237→
238→    // Pick the most recently modified session file
239→    let newest = session_files
240→        .into_iter()
241→        .filter_map(|p| {
242→            let mtime = std::fs::metadata(&p).ok()?.modified().ok()?;
243→            Some((p, mtime))
244→        })
245→        .max_by_key(|(_, mtime)| *mtime)
246→        .map(|(p, _)| p);
247→
248→    let session_path = match newest {
249→        Some(p) => p,
250→        None => return,
251→    };
252→
253→    // Import the session
254→    let data = match ClaudeCodeImporter::import_session(&session_path) {
255→        Ok(d) => d,
256→        Err(e) => {
257→            tracing::debug!("Auto-capture: failed to import session: {e}");
258→            return;
259→        }
260→    };
261→
262→    // Check for duplicates — if already imported, reuse the existing engram ID
263→    let engram_id = if let Some(existing_id) = data
264→        .manifest
265→        .source_hash
266→        .as_deref()
267→        .and_then(|h| storage.find_by_source_hash(h))
268→    {
269→        // Already imported this exact snapshot — reuse the ID
270→        existing_id
271→    } else {
272→        // New content — store the engram
273→        let id = data.manifest.id.clone();
274→        match storage.create(&data) {
275→            Ok(_) => {
276→                // Best-effort index update
277→                if let Ok(engine) = SearchEngine::open(storage) {
278→                    let _ = engine.index_engram(&data);
279→                }
280→                tracing::debug!("Auto-capture: imported engram {}", &id.as_str()[..8]);
281→                id
282→            }
283→            Err(e) => {
284→                tracing::debug!("Auto-capture: failed to store engram: {e}");
285→                return;
286→            }
287→        }
288→    };
289→
290→    // Create a temporary ActiveSession so the core handler can inject trailers
291→    let agent = data.manifest.agent.clone();
292→    let mut session = ActiveSession::new(
293→        engram_id,
294→        AgentInfo {
295→            name: agent.name,
296→            model: agent.model,
297→            version: agent.version,
298→        },
299→    );
300→    session.token_usage = data.manifest.token_usage.clone();
301→    session.auto_capture = true;
302→
303→    if let Err(e) = session.save(git_dir) {
304→        tracing::debug!("Auto-capture: failed to save session: {e}");
305→    }
306→}
307→
308→/// After post-commit, if the session was auto-created, update the engram
309→/// with the commit SHA and clean up the session file.
310→fn maybe_auto_capture_cleanup(storage: &GitStorage, git_dir: &std::path::Path) {
311→    let session = match ActiveSession::load(git_dir) {
312→        Some(s) if s.auto_capture => s,
313→        _ => return,
314→    };
315→
316→    // The core post-commit handler already recorded the commit SHA in the session.
317→    // Now read back the session to get the commit, update the engram, and clean up.
318→    let updated = ActiveSession::load(git_dir).unwrap_or(session);
319→
320→    if !updated.commits.is_empty() {
321→        // Re-read the engram, update its git_commits, and re-store it
322→        if let Ok(mut data) = storage.read(updated.engram_id.as_str()) {
323→            for sha in &updated.commits {
324→                if !data.manifest.git_commits.contains(sha) {
325→                    data.manifest.git_commits.push(sha.clone());
326→                }
327→                if !data.lineage.git_commits.contains(sha) {
328→                    data.lineage.git_commits.push(sha.clone());
329→                }
330→            }
331→            // Re-store the updated engram (overwrites the ref)
332→            let _ = storage.create(&data);
333→        }
334→    }
335→
336→    ActiveSession::cleanup(git_dir);
337→    tracing::debug!(
338→        "Auto-capture: finalized engram {} with {} commit(s)",
339→        &updated.engram_id.as_str()[..8],
340→        updated.commits.len()
341→    );
342→}
343→
344→/// If push_on_push is enabled, automatically push engram refs alongside code.
345→/// Uses the git CLI instead of libgit2 so it inherits the user's credential helpers.
346→/// Sets ENGRAM_PUSHING=1 to prevent recursive hook invocation.
347→fn maybe_auto_push(storage: &GitStorage) {
348→    // Guard against recursive invocation: our `git push` triggers pre-push again
349→    if std::env::var_os("ENGRAM_PUSHING").is_some() {
350→        return;
351→    }
352→
353→    let config = match load_config(storage) {
354→        Some(c) => c,
355→        None => return,
356→    };
357→
358→    if !config.push_on_push {
359→        return;
360→    }
361→
362→    let workdir = match storage.workdir() {
363→        Some(w) => w.to_path_buf(),
364→        None => return,
365→    };
366→
367→    match std::process::Command::new("git")
368→        .args(["push", "origin", "refs/engrams/*:refs/engrams/*"])
369→        .env("ENGRAM_PUSHING", "1")
370→        .current_dir(&workdir)
371→        .stdout(std::process::Stdio::piped())
372→        .stderr(std::process::Stdio::piped())
373→        .output()
374→    {
375→        Ok(output) if output.status.success() => {
376→            let stderr = String::from_utf8_lossy(&output.stderr);
377→            let pushed = stderr.lines().filter(|l| l.contains("->")).count();
378→            if pushed > 0 {
379→                eprintln!("engram: pushed {pushed} engram ref(s) to origin");
380→            }
381→        }
382→        Ok(output) => {
383→            let stderr = String::from_utf8_lossy(&output.stderr);
384→            tracing::debug!("Auto-push: git push failed: {stderr}");
385→        }
386→        Err(e) => {
387→            tracing::debug!("Auto-push: failed to run git: {e}");
388→        }
389→    }
390→}
391→
392→/// Load EngramConfig from the repo, returning None on any error.
393→fn load_config(storage: &GitStorage) -> Option<EngramConfig> {
394→    let config = storage.repo().config().ok()?;
395→    EngramConfig::load(&config).ok()
396→}
