  7→const CONFIG_DIR: &str = "engram";
  8→const CONFIG_FILE: &str = "repos.toml";
  9→
 10→/// Global engram configuration shared across repositories.
 11→/// Stored at `~/.config/engram/repos.toml` (or `$XDG_CONFIG_HOME/engram/repos.toml`).
 12→#[derive(Debug, Clone, Serialize, Deserialize, Default)]
 13→pub struct GlobalConfig {
 14→    #[serde(default)]
 15→    pub repos: Vec<PathBuf>,
 16→}
 17→
 18→impl GlobalConfig {
 19→    /// Get the path to the global config file.
 20→    pub fn config_path() -> Option<PathBuf> {
 21→        dirs::config_dir().map(|d| d.join(CONFIG_DIR).join(CONFIG_FILE))
 22→    }
 23→
 24→    /// Load the global config. Returns default if file doesn't exist.
 25→    pub fn load() -> Result<Self, CoreError> {
 26→        let path = Self::config_path()
 27→            .ok_or_else(|| CoreError::Config("Cannot determine config directory".to_string()))?;
 28→
 29→        if !path.exists() {
 30→            return Ok(Self::default());
 31→        }
 32→
 33→        let content = std::fs::read_to_string(&path)
 34→            .map_err(|e| CoreError::Config(format!("Failed to read {}: {}", path.display(), e)))?;
 35→
 36→        toml::from_str(&content)
 37→            .map_err(|e| CoreError::Config(format!("Failed to parse {}: {}", path.display(), e)))
 38→    }
 39→
 40→    /// Save the global config to disk.
 41→    pub fn save(&self) -> Result<(), CoreError> {
 42→        let path = Self::config_path()
 43→            .ok_or_else(|| CoreError::Config("Cannot determine config directory".to_string()))?;
 44→
 45→        if let Some(parent) = path.parent() {
 46→            std::fs::create_dir_all(parent).map_err(|e| {
 47→                CoreError::Config(format!("Failed to create {}: {}", parent.display(), e))
 48→            })?;
 49→        }
 50→
 51→        let content = toml::to_string_pretty(self)
 52→            .map_err(|e| CoreError::Config(format!("Failed to serialize config: {}", e)))?;
 53→
 54→        std::fs::write(&path, content)
 55→            .map_err(|e| CoreError::Config(format!("Failed to write {}: {}", path.display(), e)))?;
 56→
 57→        Ok(())
 58→    }
 59→
 60→    /// Add a repository path if not already present. Returns true if added.
 61→    pub fn add_repo(&mut self, path: &Path) -> bool {
 62→        let canonical = path.canonicalize().unwrap_or_else(|_| path.to_path_buf());
 63→        if self
 64→            .repos
 65→            .iter()
 66→            .any(|p| p.canonicalize().unwrap_or_else(|_| p.clone()) == canonical)
 67→        {
 68→            return false;
 69→        }
 70→        self.repos.push(canonical);
 71→        true
 72→    }
 73→
 74→    /// Remove a repository path. Returns true if removed.
 75→    pub fn remove_repo(&mut self, path: &Path) -> bool {
 76→        let canonical = path.canonicalize().unwrap_or_else(|_| path.to_path_buf());
 77→        let before = self.repos.len();
 78→        self.repos
 79→            .retain(|p| p.canonicalize().unwrap_or_else(|_| p.clone()) != canonical);
 80→        self.repos.len() < before
 81→    }
 82→}
