 90→    fn test_add_repo_deduplicates() {
 91→        let tmp = TempDir::new().unwrap();
 92→        let path = tmp.path();
 93→
 94→        let mut config = GlobalConfig::default();
 95→        assert!(config.add_repo(path));
 96→        assert!(!config.add_repo(path)); // duplicate
 97→        assert_eq!(config.repos.len(), 1);
