115→        let mut config = GlobalConfig::default();
116→        config.add_repo(tmp.path());
117→
118→        let serialized = toml::to_string_pretty(&config).unwrap();
119→        let deserialized: GlobalConfig = toml::from_str(&serialized).unwrap();
120→        assert_eq!(config.repos.len(), deserialized.repos.len());
