 37→pub fn run(args: &InitArgs) -> Result<()> {
 38→    let storage =
 39→        GitStorage::discover().context("Not inside a Git repository. Run `git init` first.")?;
 40→
 41→    if storage.is_initialized() && !args.force {
 42→        println!("Engram is already initialized in this repository.");
 43→        println!("Use --force to re-initialize.");
 44→        return Ok(());
 45→    }
 46→
 47→    storage
 48→        .init_with_remote(args.remote.as_deref())
 49→        .context("Failed to initialize engram")?;
 50→
 51→    // Install git hooks for commit trailer injection
 52→    let git_dir = storage.repo().path().to_path_buf();
 53→    hooks::install_hooks(&git_dir).context("Failed to install git hooks")?;
 54→
 55→    // Save config with smart defaults (opt-out overrides)
 56→    let config = EngramConfig {
 57→        auto_capture: !args.no_auto_capture,
 58→        push_on_push: !args.no_auto_push,
 59→        ..EngramConfig::default_init()
 60→    };
 61→    let mut git_config = storage
 62→        .repo()
 63→        .config()
 64→        .context("Failed to open git config")?;
 65→    config
 66→        .save(&mut git_config)
 67→        .context("Failed to save config")?;
 68→
 69→    // Install git alias for viewing engram notes
 70→    let _ = git_config.set_str("alias.loge", "log --notes=refs/notes/engram");
 71→
 72→    // Install Claude Code SessionEnd hook (default: on)
 73→    let claude_code_ok = if !args.no_claude_code {
 74→        if let Some(workdir) = storage.workdir() {
 75→            hooks::install_claude_code_hook(workdir).is_ok()
 76→        } else {
