 83→    // Register in global config for cross-repo search
 84→    if let Some(workdir) = storage.workdir() {
 85→        if let Ok(mut global) = GlobalConfig::load() {
 86→            if global.add_repo(workdir) {
 87→                let _ = global.save();
 88→            }
 89→        }
 90→    }
