 92→    // Auto-annotate any existing engram-linked commits
 93→    let annotated = auto_annotate_existing(&storage);
 94→
 95→    // Print summary
 96→    println!("Engram initialized. Reasoning capture is ready.");
 97→    println!();
 98→
 99→    let on = "ON ";
100→    let off = "OFF";
101→
102→    print!("  Auto-capture:     ");
103→    if config.auto_capture {
104→        println!("{on} (agent sessions imported on commit)");
105→    } else {
