139→/// Best-effort: annotate any existing engram-linked commits with git notes.
140→fn auto_annotate_existing(storage: &GitStorage) -> usize {
141→    let manifests = match storage.list(&ListOptions::default()) {
142→        Ok(m) => m,
143→        Err(_) => return 0,
144→    };
145→
146→    // Build commit SHA -> engram ID map
147→    let mut commit_to_engram: HashMap<String, String> = HashMap::new();
148→    for m in &manifests {
149→        for sha in &m.git_commits {
150→            commit_to_engram
151→                .entry(sha.clone())
152→                .or_insert_with(|| m.id.as_str().to_string());
153→        }
154→    }
155→
156→    if commit_to_engram.is_empty() {
157→        return 0;
158→    }
159→
160→    let repo = storage.repo();
161→    let sig = repo
162→        .signature()
163→        .unwrap_or_else(|_| git2::Signature::now("engram", "engram@localhost").unwrap());
164→
165→    let mut annotated = 0;
166→
167→    for (sha, engram_id) in &commit_to_engram {
168→        let oid = match git2::Oid::from_str(sha) {
169→            Ok(o) => o,
170→            Err(_) => continue,
171→        };
172→
173→        // Skip if already annotated
174→        if repo.find_note(Some(ENGRAM_NOTES_REF), oid).is_ok() {
175→            continue;
176→        }
177→
178→        let data = match storage.read(engram_id) {
179→            Ok(d) => d,
180→            Err(_) => continue,
181→        };
182→
183→        let note = format_note(&data);
184→        if repo
185→            .note(&sig, &sig, Some(ENGRAM_NOTES_REF), oid, &note, false)
186→            .is_ok()
187→        {
188→            annotated += 1;
189→        }
190→    }
191→
192→    annotated
193→}
