133→  ];
134→
135→  if (intent.summary) {
136→    lines.push("## Summary", "", intent.summary, "");
137→  }
138→
139→  if (intent.dead_ends.length > 0) {
140→    lines.push("## Dead Ends", "");
141→    for (const de of intent.dead_ends) {
142→      lines.push(`- **${de.approach}**: ${de.reason}`);
143→    }
144→    lines.push("");
145→  }
146→
147→  if (intent.decisions.length > 0) {
148→    lines.push("## Decisions", "");
149→    for (const d of intent.decisions) {
150→      lines.push(`- **${d.description}**: ${d.rationale}`);
151→    }
152→    lines.push("");
153→  }
154→
155→  return lines.join("\n");
156→}
157→
158→export function transcriptToJsonl(transcript: Transcript): string {
159→  return transcript.entries.map((e) => JSON.stringify(e)).join("\n") + "\n";
160→}
