  1→# TypeScript SDK
  2→
  3→## Installation
  4→
  5→```bash
  6→npm install @engram/sdk
  7→```
  8→
  9→## Quick Start
 10→
 11→```typescript
 12→import { EngramSession } from '@engram/sdk';
 13→
 14→const session = EngramSession.begin('my-agent', 'claude-sonnet-4-5');
 15→session.logMessage('user', 'Add OAuth2 authentication');
 16→session.logMessage('assistant', 'Implementing OAuth2 with PKCE...');
 17→session.logToolCall('write_file', { path: 'src/auth.rs' }, 'Created auth module');
 18→session.logFileChange('src/auth.rs', 'created');
 19→session.logRejection('passport.js', 'Middleware conflict with existing stack');
 20→session.logDecision('Use JWT', 'Stateless, works with load balancers');
 21→session.addTokens(1500, 800, 0.02);
 22→
 23→const id = session.commit('abc123', 'Implemented OAuth2 with PKCE');
 24→console.log(`Stored engram: ${id}`);
 25→```
 26→
 27→## Session Lifecycle
 28→
 29→1. **Begin** -- `EngramSession.begin(name, model)` creates a session
 30→2. **Log** -- Chain `log*` methods to record the session
 31→3. **Commit** -- `session.commit()` stores the engram in Git
 32→
 33→All methods return `this` for chaining:
 34→
 35→```typescript
 36→session
 37→  .logMessage('user', 'Fix the bug')
 38→  .logMessage('assistant', 'Found the issue')
 39→  .logFileChange('src/fix.ts', 'modified')
 40→  .addTokens(500, 200, 0.005);
 41→```
 42→
 43→## API Reference
 44→
 45→### EngramSession
 46→
 47→| Method | Signature | Description |
 48→|--------|-----------|-------------|
 49→| `begin` | `static begin(agentName: string, model?: string): EngramSession` | Create a new session |
 50→| `logMessage` | `logMessage(role: string, content: string): this` | Log a conversation message |
 51→| `logToolCall` | `logToolCall(toolName: string, input: string \| object, outputSummary?: string): this` | Log a tool invocation |
 52→| `logFileChange` | `logFileChange(path: string, changeType: string): this` | Log a file change |
 53→| `logShellCommand` | `logShellCommand(command: string, exitCode?: number, durationMs?: number): this` | Log a shell command |
 54→| `logRejection` | `logRejection(approach: string, reason: string): this` | Log a dead end |
 55→| `logDecision` | `logDecision(description: string, rationale: string): this` | Log a decision |
 56→| `addTokens` | `addTokens(inputTokens: number, outputTokens: number, costUsd?: number): this` | Add token usage (accumulates) |
 57→| `setSummary` | `setSummary(summary: string): this` | Set session summary |
 58→| `tag` | `tag(tagName: string): this` | Add a tag |
 59→| `parent` | `parent(parentId: string): this` | Set parent engram ID |
 60→| `build` | `build(gitSha?: string, summary?: string): EngramData` | Build without storing |
 61→| `commit` | `commit(gitSha?: string, summary?: string, storage?: GitStorage): string` | Store in Git, returns engram ID |
 62→
 63→### GitStorage
 64→
 65→| Method | Signature | Description |
 66→|--------|-----------|-------------|
 67→| `open` | `static open(path: string): GitStorage` | Open a Git repo at path |
 68→| `discover` | `static discover(startPath?: string): GitStorage` | Discover repo from path (default: `"."`) |
 69→| `create` | `create(data: EngramData): string` | Store engram, returns ID |
 70→| `read` | `read(idOrPrefix: string): EngramData` | Read engram by ID or prefix |
 71→| `readManifest` | `readManifest(idOrPrefix: string): Manifest` | Read only manifest (fast) |
 72→| `list` | `list(): Manifest[]` | List all engrams, newest first |
 73→| `delete` | `delete(idOrPrefix: string): void` | Delete engram by ID or prefix |
 74→
 75→### Types
 76→
 77→```typescript
 78→type CaptureMode = "wrapper" | "import" | "sdk";
 79→type FileChangeType = "created" | "modified" | "deleted";
 80→
 81→interface AgentInfo {
 82→  name: string;
 83→  model?: string;
 84→  version?: string;
 85→}
 86→
 87→interface TokenUsage {
 88→  input_tokens: number;
 89→  output_tokens: number;
 90→  cache_read_tokens: number;
 91→  cache_write_tokens: number;
 92→  total_tokens: number;
 93→  cost_usd?: number;
 94→}
 95→
 96→interface Manifest {
 97→  id: string;
 98→  version: number;
 99→  created_at: string;
100→  finished_at?: string;
101→  agent: AgentInfo;
102→  git_commits: string[];
103→  token_usage: TokenUsage;
104→  summary?: string;
105→  tags: string[];
106→  capture_mode: CaptureMode;
107→}
108→
109→interface EngramData {
110→  manifest: Manifest;
111→  intent: Intent;
112→  transcript: Transcript;
113→  operations: Operations;
114→  lineage: Lineage;
115→}
116→```
117→
118→### Utility Functions
119→
120→| Function | Signature | Description |
121→|----------|-----------|-------------|
122→| `newEngramId` | `newEngramId(): string` | Generate UUID v4 hex (32 chars, no dashes) |
123→| `defaultTokenUsage` | `defaultTokenUsage(): TokenUsage` | Create zeroed TokenUsage |
124→| `intentToMarkdown` | `intentToMarkdown(intent: Intent): string` | Convert Intent to Markdown |
125→| `transcriptToJsonl` | `transcriptToJsonl(transcript: Transcript): string` | Convert Transcript to JSONL |
