    const noHash: Manifest = {
      id: "abcdef1234567890abcdef1234567890",
      version: 1,
      created_at: "2024-01-01T00:00:00Z",
      agent: { name: "test" },
      git_commits: [],
      token_usage: defaultTokenUsage(),
      tags: [],
      capture_mode: "sdk",
    };
    expect(noHash.source_hash).toBeUndefined();
  });
});

